]],
[race_ed_btl]=[[
石巨人在战斗中尽可能与敌人保持距离，但是如果无法避免肉搏的话，他们会使用石头凿成的巨大棍棒战斗。

石巨人最喜爱的战术是静止不动的站着，融入周围的环境中，然后再突然上前投掷石头来突袭敌人。
]],
