s_gnt_se="石巨人长老"
s_gnt_se_var_n="回归的石巨人"
s_gnt_se_var_d="作为发展出特殊能力的石巨人，石巨人长老拥有石巨人的所有特性，除了以下不同："
s_gnt_se_fav_cls="石巨人长老拥有特殊能力以及较高的魅力值，很适合术士职业。"
s_gnt_se_traits=[[
<b c=tg>+16力量，+4敏捷，+8体质，+2感知，+6魅力：</b>与普通石巨人相比，石巨人长老更具有奥术天赋。

<b>类法术能力：</b>可施展<t=@pwr_sp_xxx c=fc_b>塑石术</t>、<t=@pwr_sp_xxx c=fc_b>石言术</t>、<t=@pwr_sp_xxx c=fc_b>化石为泥或化泥为石</t>，每天各一次，豁免难度等级基于魅力调整值，施法者等级等同角色等级。{hr_splk}
]]-- 一些石巨人可以发展出一些与其环境相关的特殊能力。这些石巨人长老的魅力值至少有15而且还能如等级10的术士一样施展其类法术能力。每天一次他们可以使用塑石术，石言术，以及化石为泥或化泥为石 (DC 17)。豁免检定DC基于魅力调整值。每10名长老中会有1名术士，其等级通常为3-6。Some stone giants develop special abilities related to their environment. Called elders, these stone giants have Charisma scores of at least 15 and spell-like abilities, which they use as 10th-level sorcerers. Once per day they can use stone shape, stone tell, and either transmute rock to mud or transmute mud to rock (DC 17). The save DC is Charisma-based. One in ten elders is a sorcerer, usually of 3rd to 6th level.	pf 三种类法术能力（施法者等级10）。石巨人长老获得+1挑战等级。 three spell-like abilities (CL 10th). Stone giant elders add +1 to their CR.
s_gnt_se_hr_splk="塑石术，石言术，化石为泥或化泥为石。"
s_gnt_se_d=[[
年长的石巨人会离开它们的部落，这是它们晚年中的一段重大时期，它们会选择隐居或尝试融入其他类人生物文明之中。

经过这种数十年的自我流放，那些回来的石巨人就成为了石巨人长老。

这些石巨人长老发展出一些与其环境相关的特殊能力，还能如术士一样施展这些能力。
]]


-- 精类		Fey


s_sprite	= "小妖精"
s_sprite_c	= "这个轻盈而小巧的生物，看起来就像一个有着纤细的蛾子翅膀和细长耳朵的人。"
s_sprite_d	= [[小妖精是隐居的妖精。它们以自己的方式对抗邪恶保护家园。小妖精聚居在森林深处，守护着大自然。一个部族的小妖精会认为它们自己是它们领地内某个特定的人物、地点或生物的保护者，即便其实际上并不需要保护。

小妖精的身体天生会发光，不过小妖精能按自己的意愿改变其颜色和亮度。在死亡后不久，小妖精的身体就会融化成闪亮的蒸汽。小妖精是最小的精类之一，站起来仅高9寸，很少超过1或2磅重。

小妖精使用类法术能力与迷你武器来进行战斗。它们喜欢使用埋伏和其他计谋远胜于正面冲突。]]

s_sprite_e	= [[小妖精在许多方面比大多数精类要更加原始。它们享受彼此陪伴，但不信任其他精类，并认为任何不是它们要选择保护的类人生物或其他生物都是要对它们不利的。就算是动物也通常被看作是危险的。这很大程度上是由于它们的小体型容易让它们成为捕食者的目标所致。因此小妖精对于危险通常的第一反应都是逃跑——用它的类法术能力耽搁或混乱追捕者，然后依赖其飞行速度和体型来使其最终得以逃离。

虽然小妖精本身蒙昧而原始，但它们对所有魔法事物都有着旺盛的好奇心。它们特别感兴趣有着巨大潜在魔法力量的地点，比如古代庙宇的废墟。这种好奇心使它们意外的能接受充当魔宠的角色。一个5级的拥有进阶魔宠专长的混乱中立施法者，可以将小妖精作为魔宠。]]


s_nymph		= "宁芙"
s_nymph_c	= "一个绝美的身影自水中升起，尖尖的长耳生在头的两侧，如此完美的容颜令人胸中作痛。"
s_nymph_d	= [[宁芙，也称为水妖精，不仅是自然界美丽的化身，同时也是野生密境的守护人。她们拥有令人无法抵挡的美貌，以至于对她们随意的一瞥便能使看见她们的人立刻目盲。

宁芙身高和体重与女性精灵差不多。宁芙说木族语和通用语。

许多人寻求宁芙的美丽，枉自丢掉了性命；更多人被宁芙的美丽所慑，陷入迷恋与疯狂无法自拔。

但宁芙并不是残忍的生物——她是大自然最纯美秘境的守卫者，对那些尊重她与她的家园的人心怀善意，甚至会对某个人表现好感，让他带走她的魔法赠礼。

然而，那些试图侵犯或伤害她和她家园的人很快会发现，她的美貌背后隐藏着自然守护者的强大力量，用来自保绰绰有余。]]


s_pipes="牧笛"
s_pipes_d=[[半羊人能用他们的牧笛演奏多种魔法旋律。

演奏时，所有处于60英尺扩散范围内的生物（半羊人除外）都必须通过DC13的意志检定，否则会受到魅惑人类、睡眠或惊恐术的法术效果影响（施法等级10；半羊人可选择旋律和效果）。

本能力的豁免检定DC基于魅力。任何通过意志检定的生物，24小时内不受同样效果影响。

通常一群半羊人中只有一个携带牧笛。如果落入其它生物手中，牧笛会失去特殊能力。]]-- pf 萨特羊人可以用牧神笙吹出萦绕的旋律来强化他的魔法。他吹奏时，60尺半径内的所有生物必须通过ＤＣ１８的意志豁免，否则受到魅惑人类（Charm Person）、恐惧术（Fear）、睡眠术（Sleep）或暗示术（Suggestion）的影响，效果取决于萨特羊人吹奏何种旋律。成功通过任何一种旋律的意志豁免的生物免疫同一组牧神笙的效果２４小时，但萨特羊人的其他类法术能力仍然正常影响他。吹奏牧神笙不消耗萨特羊人的每日类法术能力次数，如果他失去了牧神笙，他依然可以施展通常的能力。牧神笙总是精制品，萨特羊人可以用一星期时间制作一个新的。此能力的豁免ＤＣ基于魅力。A satyr can focus and empower his magic by playing haunting melodies on his panpipes. When he plays, all creatures within a 60-foot radius must make a DC 18 Will save or be affected by charm person, fear, sleep, or suggestion, depending on what tune the satyr chooses. A creature that successfully saves against any of the pipes' effects cannot be affected by the same set of pipes for 24 hours, but can still be affected by the satyr's other spell-like abilities as normal. The satyr's use of his pipes does not count toward his uses per day of his spell-like abilities, and if separated from them he may continue to use his standard abilities. The pipes themselves are masterwork, and a satyr can craft a replacement with 1 week of labor. The save DC is Charisma-based.

s_satyr="半羊人"
s_satyr_c="这个咧嘴微笑的英俊男子长着一双山羊腿，弯曲的羊角从他额头两侧伸出。"
s_satyr_fav_cls="半羊人热爱音乐，具有音乐天赋，牧神笙因他们而得名。半羊人可以用牧神笙编织出千变万化的魔法旋律来魅惑他人。"--..add_hr("半羊人的天赋职业暂由吟游诗人改为术士。")..add_hr("Changed satyrs' favored class from Bard to Sorcerer temporarily.")..add_hr("Cambiata temporaneamente la classe preferita dei satiri da Bardo a Stregone.")
s_satyr_traits=[[
<b c=tg>+2敏捷，+2体质，+2智力，+2感知，+2魅力：</b>除了不太强壮，半羊人天生优雅灵活，感官敏锐，在各方面都表现不俗。

<b>种族生命骰：</b>半羊人初始拥有5个妖精等级，给予它5d8生命骰。

<b>种族技能：</b>半羊人的妖精等级给予它8 x (2 + 智力调整值)的技能点数。其本职技能为唬骗、隐藏、潜行、侦察、聆听、表演、知识(自然)。它在隐藏、潜行、侦察、聆听、表演检定上有+4种族加值。

<b>种族专长：</b>半羊人的妖精等级给予它2个专长。半羊人获得机警作为奖励专长。

<b>防御：</b>+4天生防御加值。

<b>天生武器：</b>抵撞（1d6）。{hlp_nwpn}

<b>武器擅长：</b>擅长简易武器、短弓。

<b>特殊能力：</b><t=@pwr_pipes c=fc_b>牧笛</t>，<t=@pwr_dr5_cdir c=fc_b>伤害减免5/寒铁</t>。
]]-- 基本攻击加值+2，基本豁免加值强韧+1，反射+4，意志+4。a base attack bonus of +2, and base saving throw bonuses of Fort +1, Ref +4, and Will +4.
s_satyr_langs=[[
<b>初始语言：</b>木族语。
<b>额外语言：</b>通用语、精灵语、侏儒语。

<c=twc>半羊人讲木族语，并有许多会说通用语。</c>
]]
s_satyr_m=[[
半羊人在一些地区被称为牧神，他们是享乐放荡的生物，生活在森林深处，热爱美酒、音乐和肉体愉悦，喜欢勾引未经人事的少女和牧童。

半羊人通常担任着森林生物守护者的职责，他们可以用牧神笙编织出千变万化的魔法旋律来魅惑他人。

半羊人的头发是红色或棕色，而蹄和角是深黑色，身高和体重与半精灵差不多。

半羊人讲木族语，并有许多会说通用语。
]]
s_satyr_d=[[
半羊人，也称为萨特或萨特羊人，在一些地区被称为牧神。他们是享乐放荡的生物，生活在森林深处，热爱美酒、音乐和肉体愉悦，喜欢勾引未经人事的少女和牧童。

尽管半羊人拥有健壮而阳刚的男子身躯，他们诱骗少女的主要资本是音乐天赋，牧神笙因他们而得名。半羊人可以用牧神笙编织出千变万化的魔法旋律来魅惑他人。

除了永无休止的嬉戏玩乐之外，半羊人通常担任着森林生物守护者的职责。
]]
s_satyr_eds={
[race_ed_dd1]=[[
半羊人在一些地区被称为牧神，他们是享乐放荡的生物，生活在森林深处，热爱美酒、音乐和肉体愉悦，有着浪荡不羁和油嘴滑舌的名声，喜欢勾引未经人事的少女和牧童，把事后一大堆尴尬的解释和意外的怀孕留给人家去操心。

与半羊人云雨过后生下的孩子总是纯血半羊人，通常很快就会被他放荡的亲族拐走。尽管半羊人重视自己的愉悦远胜于他人的权利，他们对被引诱者没有恶意。

尽管半羊人拥有健壮而阳刚的男子身躯，他们诱骗少女的主要资本是音乐天赋。牧神笙因他们而得名。半羊人可以用牧神笙编织出千变万化的魔法旋律来魅惑他人，让他们掉进他的欲望陷阱之中。

除了永无休止的嬉戏玩乐之外，半羊人通常担任着森林生物守护者的职责，那些成功把半羊人的欲望转为愤怒的家伙会发现自己面对着一位被危险生物围绕着的牧神。
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
半羊人拥有健壮而阳刚的男子身躯，头发是红色或棕色，而蹄和角是深黑色。

半羊人的身高和体重与半精灵差不多。
]],
[race_ed_btl]=[[
半羊人敏锐的感官让他在户外几乎不可能被突袭。相反，凭着他们天生的优雅与灵活，半羊人可以潜行到没有小心观察周围荒野的旅行者身边。

一旦战斗展开，徒手的半羊人会以有力的抵撞进行攻击。预期到可能遇到麻烦的半羊人，会装备弓和匕首，并在敌人接近前就从躲藏处射箭削弱对手。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
