-- 人形怪物	Monstrous Humanoid


s_powerful_charge		="强力冲刺"
s_powerful_charge_d		=[[牛头人的战斗通常以冲锋对手开始，低下头用强有力的双角冲进战场。

每场战斗的首次冲锋额外加上2倍抵撞伤害。]]-- 这次攻击除了冲刺动作本身的优势和风险外，还将以+9的攻击加值进行单一一次抵撞攻击，并造成4d6+6点伤害。In addition to the normal benefits and hazards of a charge, this allows the beast to make a single gore attack with a +9 attack bonus that deals 4d6+6 points of damage.

s_natural_cunning		="天性狡猾"
s_natural_cunning_d		=[[虽然牛头人不是特别聪明，但它们拥有天生的狡猾和逻辑能力。

这使得它们免疫迷宫术，绝不会迷路，还能追踪敌人。

此外，它们永远不会陷入措手不及状态。]]

s_minotaur="牛头人"
s_minotaur_c="有着健壮的人类躯体和喷气的公牛头颅，这个生物的双蹄来回刨地，像是准备冲锋。"
s_minotaur_fav_cls=""
s_minotaur_traits=[[
<b c=tg>+8力量，+4体质，<c=tr>-4智力，-2魅力：</c></b>牛头人非常强壮坚韧，但是它们生于诅咒，心智扭曲，极其记仇。

<b>种族生命骰：</b>牛头人初始拥有6个人形怪物等级，给予它6d8生命骰。

<b>种族技能：</b>牛头人的人形怪物等级给予它9 x (2 + 智力调整值)的技能点数。其本职技能为跳跃、搜索、侦察、聆听、威吓。它在搜索、侦察、聆听检定上有+4种族加值。

<b>种族专长：</b>牛头人的人形怪物等级给予它3个专长。

<b>防御：</b>+5天生防御加值。

<b>天生武器：</b>抵撞（1d8）。{hlp_nwpn}

<b>武器擅长：</b>擅长简易武器、巨斧。

<b>特殊能力：</b><t=@pwr_powerful_charge c=fc_b>强力冲刺</t>，<t=@pwr_natural_cunning c=fc_b>天性狡猾</t>，<t=@pwr_scent c=fc_b>灵敏嗅觉</t>。
]]-- +6的基本攻击加值，基本豁免加值为强韧+2，反射+5，意志+5。a base attack bonus of +6, and base saving throw bonuses of Fort +2, Ref +5, and Will +5.
s_minotaur_langs=[[
<b>初始语言：</b>通用语、巨人语。
<b>额外语言：</b>兽人语、地精语、土族语。

<c=twc>牛头人说巨人语。</c>
]]
s_minotaur_d=[[
牛头人有着壮硕的人类躯体和公牛的头颅，站立时超过7英尺高，体重约700磅。

没有什么像牛头人一样记仇。很多文化中都有关于牛头人起源的传说，提到被轻视的记仇神祗将人类扭曲形态，夺走心智与美貌，安上牛头来作为惩罚。

但绝大多数现代牛头人对此嗤之以鼻，认为自己不是神的玩物，而是被称为巴风特的强大残忍恶魔领主制造的典范生物。
]]
s_minotaur_eds={
[race_ed_dd1]=[[
没有什么像牛头人一样记仇。无数世纪前遭到文明种族的轻视，因神降下的诅咒而生，牛头人为了报复最细小的不敬，无论是真实还是妄想，不断的猎杀，屠戮和吞吃其他次等的类人生物。

很多文化中都有关于牛头人起源的传说，提到被轻视的记仇神祗将人类扭曲形态，夺走心智与美貌，安上牛头来作为惩罚。但绝大多数现代牛头人对此嗤之以鼻，认为自己不是神的玩物，而是被称为巴风特的强大残忍恶魔领主制造的典范生物。
]],
[race_ed_dd2]=[[
传统的牛头人的巢穴是个迷宫。包括用来迷惑他人的正式迷宫，无意产生的迷宫——比如城市下水道，以及自然形成的迷宫，比如交错的洞穴和地底通道。

借助他们天生的狡猾，牛头人用它们的迷宫巢穴困住前来找麻烦的粗心敌人和误打误撞的迷路者，慢慢地猎杀它们。只有彻底征服了绝望的目标时，牛头人才会予以最后一击。

当对付一群敌人时，牛头人通常会放走一个活口，来散布恐怖并引诱其他的敌人来猎杀自己。当然对于牛头人来说，这些想当英雄的家伙味道好极了。
]],
[race_ed_dd3]=[[
牛头人也可能被更强大的怪物和邪恶生物统领，只有任其猎杀捕食它们就没有怨言。

一般来说这意味着守卫强大的物件和重要的地点，或者是普通的佣兵任务，猎杀主人的敌人。
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
]],
[race_ed_btl]=[[
牛头人偏好近战，因为此时它们的强大力量能彻底发挥作用。

牛头人战斗起来很直接，战斗一开始就用可怕的犄角捅穿最近的敌人。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_centaur_charge		="人马冲锋"
s_centaur_charge_d		="人马使用长武器进行冲锋时会造成双倍伤害，就如同马背上的骑士一样。"-- 长枪 lance

s_centaur="人马"
s_centaur_c="这种生物的上半身是一个古铜色皮肤、经验丰富的战士，下半身则是一匹皮毛光滑的战马。"
s_centaur_fav_cls="人马生活在辽阔的平原或可怕的森林边缘，它们是传奇的猎手和战技纯熟的战士。"
s_centaur_traits=[[
<b c=tg>+8力量，+4敏捷，+4体质，+2感知，<c=tr>-2智力：</c></b>人马强壮坚韧，身体灵活又警觉，但通常愚钝且野蛮。

<b>种族生命骰：</b>人马初始拥有4个人形怪物等级，给予它4d8生命骰。

<b>种族技能：</b>人马的人形怪物等级给予它7 x (2 + 智力调整值)的技能点数。其本职技能为聆听、潜行、侦察、生存。

<b>种族专长：</b>人马的人形怪物等级给予它2个专长。

<b>防御：</b>+3天生防御加值。

<b>武器和盔甲擅长：</b>擅长简易武器、军用武器（重刃、弓）。

<b>特殊能力：</b><t=@pwr_centaur_charge c=fc_b>人马冲锋</t>。
]]
s_centaur_langs=[[
<b>初始语言：</b>木族语、精灵语。
<b>额外语言：</b>通用语、侏儒语、半身人语。

<c=twc>人马一般只会说木族语和精灵语，相对聪明的个体也会说通用语。</c>
]]
s_centaur_d=[[
人马是传奇的猎手和战技纯熟的战士，它们是半人半马的生物。

人马是一个古老的种族，只能慢慢接受现代世界。极少数情况下，某些进步领袖所领导的整个部族都会和类人生物的群落进行交易甚至结盟。

虽然大多数人马依然生活在辽阔的平原或可怕的森林边缘，但是也有许多人抛弃了祖先孤立的生活方式而进入大都市生活。
]]--人马约有7尺高2100磅重。A centaur is about 7 feet tall and weighs about 2,100 pounds.人马德鲁伊通常是部落的领袖兼发言人。A centaur druid is usually a tribe’s designated leader and speaker.
s_centaur_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
人马是半人半马的生物，它们像重型马一样大，但是要比重型马高很多而且还要稍微重一些。

人马通常出现在文明的边缘地带，这些坚忍的生物外表上体现出很大差异，它们的肤色黝黑，和附近地区的人类相似，但是下半身却有着马匹的色泽。

人马的发色和瞳色通常是深色，脸部宽阔，而身体的大部分则受到下半身体型的影响。所以一般来说人马站立超过7尺高，重量超过2000磅，它们的体型差异较大——从瘦小的平原行者到壮实的山地猎手。

人马一般来说能活60岁。人马说木族语和精灵语。
]],
[race_ed_btl]=[[
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
人马远离其他种族，同类之间也有争端。人马是一个古老的种族，只能慢慢接受现代世界。

极少数情况下，某些进步领袖所领导的整个部族都会和人形生物的群落进行交易甚至结盟——比如精灵，但有时是侏儒、人类或矮人。

许多种族小心提防着人马，大部分是由于传说中人马野蛮而领土意识很强，并且它们和顽固的殖民者与扩张性国家常常产生强烈的冲突。
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
虽然大多数人马依然生活在辽阔的平原或可怕的森林边缘，但是也有许多人抛弃了祖先孤立的生活方式而进入大都市生活。

通常这些自由而英勇的人马被认为遭到了部落放逐，下定决心离开它们的部族。
]],
[race_ed_nam]=[[
]],
}


s_medusa	= "梅杜莎"
s_medusa_c	= "这位纤细、冶丽的女子有着一对闪烁著诡异光采的双眼，还有一头嘶嘶作响的蛇发。"
s_medusa_d	= [[梅杜莎，也称为蛇发女妖，是一种外型似人，但有着一头蛇发而非长发的生物。若是梅杜莎戴着某物来盖住她那盘卷纠结的蛇发，从三十呎或更远处看去，她是很有可能被误认为美丽的女子的——若她以衣物遮掩住脸部与头部，即使在更近的距离内都可能被误认为人类。

梅杜莎有5到6尺高，并且差不多和人类一样重。梅杜莎说通用语。

梅杜莎习惯将自己的真面目伪装起来用各种说辞和骗术让目标确认没有危险，直到受害者进入其石化凝视射程范围之内。梅杜莎会使用一般的武器来攻击那些避开其视线或幸存下来的敌人，同时利用其剧毒的蛇发来攻击邻近的敌人。]]--在30尺距离之外（或更近，如果它的脸遮起来的话）梅杜莎看起来和人类毫无二致。此生物通常穿着能加强身体曲线的衣服，并用兜帽或面纱遮起脸。

s_medusa_e	= [[梅杜莎以谎言与伪装来隐藏她们的面容，直到距离近得足以让她们对敌人施展石化凝视，但同时她们也性喜从远处以箭矢打击敌人，引诱他们掉入陷阱之中。

有少数梅杜莎酷爱用这些悲惨的受害者所制成的复杂装饰来妆点她们沼泽中的巢穴，但是大多数的梅杜莎则会小心地隐藏前一个受害者存在的迹象，这样下一个敌人才不会先对她们的存在心怀警戒。

由于习于隐匿自己的样貌，在城市中生活的梅杜莎经常是游荡者，而她们荒野中的同类则会伪装成巡林客或是追踪者。然而，那些最传奇也最恶名远播的梅杜莎，则具有吟游诗人或者牧师的等级。

由于她们风姿绰约又聪慧机敏，生活在都市的梅杜莎经常会与盗贼公会或者其他地下世界的黑暗势力有所关联。梅杜莎可能会跟目盲的生物或者有智慧的不死生物结成同盟，因为这两者皆免疫她的石化凝视。

会施法的梅杜莎通常是先知或者预言者，有着声明远播的强大能力或恶名远播的过往，并居住在偏僻之地。这些作为先知的梅杜莎对于她们的职责相当投入，若赠予她们足够份量的赠礼与合适的奉承，她们所能告知的秘密会相当地有用。

当然，这些强大生物的巢穴中毫不避讳地摆放着那些无礼冒犯之人的塑像，因此想从她们身上探寻知识的人会被告诫要在这样的会面中保持谨慎。

所有已知的梅杜莎都是女性。少见地，梅杜莎可能会选择一名雄性的人形生物作为她的伴侣，通常是借由爱情灵药或者类似法术的帮助，而她会非常小心不要石化这名爱情的犯人——至少直到她开始厌烦他的陪伴为止。]]


s_harpy		= "鹰身女妖"
s_harpy_c	= "这个生物看起来像是一个外表狂野的女性，但是长着褴褛的翅膀和鸟爪一样的双脚。"
s_harpy_d	= [[鹰身女妖，也称为人面鸟妖，这种生物看起来像是一个外表狂野的女性，但是长着褴褛的翅膀和鸟爪一样的双脚。

鹰身女妖偏爱以她们充满魔力的歌声诱惑那些不幸的旅行者，然后将他们置于无法形容的折磨中。只有当鹰身女妖厌倦了她的新“玩具”时才会让他们解除这些苦难—也就是把他们杀了吃掉。

鹰身女妖喜欢穿戴从受害者身上取得的珠宝或饰品，因为她们易于沉湎于人类饰品的闪亮光芒中。如果靠近这些生物的话，会闻到她们身上散发出被害者的尸臭。所以她们很少让未被迷魂的生物太过接近，免得他们闻到羽毛上腐烂的气息。因此许多鹰身女妖都会在身上涂抹香料或香油。

出现在不同地域的鹰身女妖在外表上截然不同。一些看起来像是秃鹫和女性的混合体，而另一些则有猎鹰一般威严的羽毛。一些生活在与世隔绝的热带岛屿的鹰身女妖甚至有鹦鹉一般五彩的羽毛。]]

s_harpy_e	= [[鹰身女妖通常被视作堕落腐败的邪恶之物，她们了解生物如何思考和行动。这种理解在她们寻找最爱的猎物时让她们占尽优势。

虽然野外的生物很容易就成为她们迷魂曲的牺牲品，但其实这些卑鄙的鸟人更喜欢品尝那些以各种复杂情绪为佐料的智慧生物。简单的猎物味如嚼蜡。

虽然极度野蛮且对自己的行为从无悔改，大多鹰身女妖定居于人型生物社会附近，并且乐于周旋于那些被她们视作“食物”的生物之间。


<b>鹰身女妖射手</b>
残酷的猎人和游荡的强盗，鹰身女妖射手被训练成精通远程战斗的战士。鹰身女妖射手经常作为雇佣兵，把她们的服务卖给出价最高的人。在没有工作的时候，她们会以拦路强盗的身份来维持生计，迫使来往商队支付保护费。]]


s_hag		= "鬼婆"
s_hag_d		= [[虽然不同的鬼婆拥有独特的外貌与习性，但也有许多共同点，它们都有着干瘪的丑老太婆的外型，佝偻的身躯掩饰了可怕的力量与敏捷的动作。

鬼婆十分强壮。它们对法术具有天然的抗力，并且会施展自己的魔法。鬼婆常常集结成战团，每个群体通常包含各种鬼婆，这样便可以使用各种类的能力。

鬼婆说巨人语和通用语。]]


-- 异界生物	Outsider


s_celestial_creature	= "天界生物"
s_celestial_creature_d	= [[天界生物居住于上层位面，善良的领域，尽管在主物质界能找到与它们相类似的生命。它们比它们在俗世对应生物们更加华丽漂亮。

天界生物通常展现出金属般的色彩 (一般为银色，金色或白金色) 。它们可能会被误认为是天界生物与非天界生物交配产生的半天界或者更强的生物。]]


s_fiendish_creature		= "炼狱生物"
s_fiendish_creature_d	= [[炼狱生物居住在邪恶的下层位面，但在主物质位面也能找到与它们类似的生命。和俗世间的类似生物相比，它们拥有更加可怕的外貌。]]


s_half_celestial	= "半天界生物"
s_half_celestial_d	= [[不论其形态，半天界生物看起来总是令人赏心悦目，它们有金色的皮肤，闪亮的眼睛，天使般的翅膀，或其他能显示它们高贵血统的标志。]]


s_half_fiend	= "半炼狱生物"
s_half_fiend_d	= [[不论其形态，半炼狱生物总是不堪入目，它们有黑色的鳞片，犄角，闪烁着红光的眼睛，蝙蝠一样的翅膀，恶臭的体味，或者其他能显示它们受到邪恶污染的特征。]]


s_angel		= "天使"
s_angel_d	= [[天使是天界生物的一支，或者是善良的异界生物。他们居住在善良阵营的外位面。

天使可以是任意善良阵营。无论他们的阵营为何，天使永远不撒谎，欺骗或偷窃。他们所有的行为都完美无缺的使人感到敬佩，这些行为经常显示他们是所有天界生物中最老练，并最可信赖的。

所有的天使都长的十分秀丽，尽管他们的容貌差异很大。

天使说天界语，炼狱语和龙语，尽管他们可以通过自己的巧言能力来和几乎任何生物交流。]]


s_archon	= "神使"
s_archon_d	= [[神使，也称为亚空神族，是天界生物的一支，或者是善良的异界生物。他们居住在守序善良阵营的外位面。

神使说天界语，炼狱语和龙语。但她们可以通过自己的巧言能力来和几乎任何生物交流。]]


s_demon		= "恶魔"
s_demon_d	= [[恶魔生活在混乱邪恶位面，他们是凶残的化身。仅仅为了取乐，恶魔就会攻击其他任何生物——甚至包括他们的同类。

恶魔说深渊语，天界语和龙语。]]


s_devil		= "魔鬼"
s_devil_d	= [[魔鬼是来自于守序邪恶位面的炼狱生物。

多数魔鬼身体周围都环绕著邪恶灵气，它们会利用这个灵气打散战力很强的敌人队伍，然后再逐一击败各个对手。

拥有类法术能力的魔鬼会使用它们的幻术能力尽可能地欺骗和迷惑对手。它们最喜欢玩的把戏是创造一支由幻像构成的增援部队，敌人永远无法确定这威胁仅仅是虚假幻觉还是被召唤来加入战斗的真正魔鬼。

魔鬼说炼狱语，天界语，和龙语。]]


s_planetouched		= "神魔裔"
s_planetouched_d	= [[神魔裔是一种通称，用来描述那些可将其血缘回溯到异界生物（通常是炼狱生物或天界生物）的对象。

当一个人的遗传中拥有超自然的本质时，此效果可以延续好几个世代之久。虽然外观上不会像半天界或半炼狱生物那样有着戏剧性的变化，但神魔裔仍然保留了一些特殊能力。

阿斯莫和泰夫林是最常见的神魔裔。阿斯莫是带有天界血统的人类，而泰夫林的家谱中往往会有一些炼狱生物。]]


s_aasimar		= "阿斯莫"
s_aasimar_c		= "这个有着不寻常美貌的女子看起来像人类，给人一种冷静，善良的感觉。"
s_aasimar_d		= [[阿斯莫，也称神裔，通常高挑，容貌姣好而且一般都很讨人喜欢。一些阿斯莫的身体特征暗示着他们的血统，比如银发、金眼或异乎寻常的目光。

大部分的阿斯莫都很明确的属于善良阵营。他们会对抗邪恶，并试图影响他人去做正确的事。偶尔他们也会因其天界祖先的个性而做出复仇或判罚的行为，但是这很罕见。]]--pf神裔是受到天界祝福的生物，她们的外貌像是人类，却有着指向自身上界血脉的独有特征。神裔几乎总是美丽脱俗，而她们也可能沾染到人性的各个方面——尽管邪恶之徒只是少数而已，她们并不全是善良之辈。Creatures blessed with a celestial bloodline, aasimars seem human except for some exotic quality that betrays their otherworldly origin. While aasimars are nearly always beautiful, something simultaneously a part of and apart from humanity, not all of them are good, though very few are evil.
s_aasimar_fav_cls="阿斯莫通常喜欢公平而直接的竞赛。然而，在对抗邪恶的敌人时，他们会抱着坚定的信念战斗至死。"
s_aasimar_traits=[[
<b c=tg>+2感知，+2魅力：</b>阿斯莫富有洞察力、自信且风度翩翩。

<b>技能熟练：</b>侦察、聆听检定有+2种族加值。]]
.."\n\n"..xs_lbl("s_res_ace_5")
.."\n\n".."<b>类法术能力：</b>每天可施展一次<t=@pwr_sp_lt_3 c=fc_b>昼明术</t>，施法者等级等同角色等级。"-- 种族专长：阿斯莫通过其职业等级获取专长。	Racial Feats: An aasimar gains feats according to its class levels.
s_aasimar_langs=[[
<b>初始语言：</b>通用语、天界语。
<b>额外语言：</b>龙语、矮人语、精灵语、侏儒语、半身人语、木族语。

<c=twc>阿斯莫说通用语和天界语。</c>
]]
s_aasimar_eds={
[race_ed_dd1]=[[
神裔是拥有天界或其他善良异界显著血统的人类。虽然不全是仁慈之辈，神裔明显地有着行善弃恶的倾向，他们对天界的信仰或认同非常坚定。

神裔的遗传可以潜藏数代，却突然地出现在双亲分明是人类的小孩身上。多数社会把神裔的降生视为吉兆；不过也有记载表明，有些神裔利用自己的身份和名望犯下残虐无道的暴行，颠覆了人们对他们普遍的印象。“我永远是你最不会怀疑的人”，这是那些邪恶神裔信奉的至理。他们往往有着杰出市民或虚伪英雄的一副面孔，将堕落的另一张面孔深深掩藏。好在这些反例都是凤毛麟角。
]],
[race_ed_dd2]=[[
阿斯莫是有着天界或者其他善良的异界先祖血统象征的人类。阿斯莫并不都是善良的，但是善良是他们的本性，并且他们会被有着善良信仰或者组织的天界伙伴吸引。

阿斯莫的血统会一连几代地被隐藏，但却会突然在双亲明显为人类的孩子身上显现。大部分组织表明，阿斯莫出生时会伴随好兆头。

阿斯莫看起来几乎跟人类一样，除了一些身体上的小细节显露了他那不一般的血统。标准的阿斯莫生物头发有着金属光泽，不一般的瞳色和肤色或者甚至发出金色光环。
]],
[race_ed_phy]=[[
除了某些揭示非凡血统的细节特征，神裔看上去和人类并无区别。

典型的神裔特征包括金属光泽的头发、宝石瞳孔的眼睛、细腻皎洁的肌肤，甚至还有头顶闪耀的金色光环。
]],
[race_ed_btl]=s_aasimar_fav_cls,
[race_ed_soc]=[[
很难说神裔拥有自己的社会。他们作为人类的一枝，适应了周遭环境，并活跃在矫正不公、抚平伤恸等与社会阴暗面斗争的舞台上。

在某些暴政大行其道的国度，这些行为使他们站到了法律的对立面；但神裔在必要时也会谨慎而机智，使自己能够避免受到压迫者的注意。

虽然邪恶神裔可能独行、或是建立让自身罪孽得以遁形的地下结社，正气凛然的神裔们通常会聚集在善良组织的旗下，尤其（但非绝对）是教会等宗教团体。
]],
[race_ed_rel]=[[
神裔在人类社会中最为常见，他们也最习惯生活在人类中。对那些天界血统比较淡薄的神裔来说尤为如此。

为何天界更青睐人类而非其他种族依然原因不明，可能是因为人类的遗传基因与其最为亲和、适于完成向神裔的进化。又或许，是那些种族的特征过于棱角分明，难以改变也说不定。无论其他种族是否与上层位面的存在有过“亲密接触”，他们之间确实少有子嗣、更未出现过神裔。

不过，虽然神裔更偏向人类社会，他们也能自如地生活在其他任何环境中。他们拥有与生俱来的优雅社交性，风度翩翩而又值得信赖。他们和半精灵关系亲密，因为双方有着人类近亲的共性；但和半兽人之间相对冷淡，因为对方难有耐性来应对神裔过分华美的用辞和容颜。精灵执政者有时会驱逐神裔，并责难他们过于依靠天生妩媚来掩盖失礼之举。也许在所有种族中侏儒对神裔最为倾心，对他们多变的容貌和神秘的血统长久地保持好奇和尊重。
]],
[race_ed_aln]=[[
神裔是最倾向于善良阵营的种族，但这并非绝对，也有神裔背弃公正、投身于堕落的无底深渊。

大多数神裔崇拜象征荣耀、英勇、守护、治愈和救难的神祇，或信仰家园、社群或家庭等质朴的概念。也有些神裔走上了艺术、音乐和知识之道，从美中寻找真理和智慧。
]],
[race_ed_adv]=[[
由于对人类社会的归属感不足、或感召于自身伟大使命，常有神裔成为冒险者。

牧师和圣骑士是他们最多见的选择，而吟游诗人和术士这些奥术职业中神裔的身影也不鲜见。神裔野蛮人很稀罕，但一旦降生于某些部落，他们往往会领导和鼓舞整个氏族皈依天界图腾之下。
]],-- 牧师、先知...术士和召唤师	, oracles,	summoners
[race_ed_nam]=[[
<c=twa>常见男名：</c>
阿里申（Aritian），贝廷（Beltin），塞南（Cernan），克隆威尔（Cronwier），厄兰（Eran），艾拉敏（Ilamin），毛德利（Maudril），奥克林（Okrin），帕兰特（Parant），图洛（Tural），卫兰（Wyran），塞坎（Zaigan）。

<c=twa>常见女名：</c>
阿柯恩（Arken），阿欣诺（Arsinoe），达薇娜（Davina），德琳玛（Drinma），艾美萨（Imesah），玛索吉（Masozi），妮婕娜（Nijena），妮拉莫（Niramour），翁德莱（Ondrea），莉雅拉（Rhialla），瓦尔提拉（Valtyra）。
]],
}


s_tiefling		= "泰夫林"
s_tiefling_c	= "这个瘦长高挑的男人冷笑着拔出自己的剑，头上小小的角和身后带刺的尾巴说明他并非寻常人类。"
s_tiefling_d	= [[泰夫林，也称魔裔或提夫林，是沾染魔族血统的凡人，起源不一、常出现在类人生物的社群中。

其他种族很少信任他们，而这种同情的缺少恰恰又常逼泰夫林寻求血脉中堕落部分的支持。

少数泰夫林将这种与黑暗欲望的搏斗视为踏上英雄之旅的动力。]]--3r许多泰夫林和人类没有差别。一些泰夫林有小角、尖牙、红眼、身上弥漫着硫磺味甚或有蹄的脚。没有任何两个泰夫林会长得一模一样。泰夫林总是偷偷摸摸且虚伪狡猾的。他们喜欢发动突袭，并会尽可能地避开公平的战斗。Many tieflings are indistinguishable from humans. Others have small horns, pointed teeth, red eyes, a whiff of brimstone about them, or even cloven feet. No two tieflings are the same. Tieflings are sneaky, subtle, and generally conniving. They prefer to strike from ambush and usually avoid a fair fight if they can.
s_tiefling_fav_cls="泰夫林总是偷偷摸摸且虚伪狡猾的。他们喜欢发动突袭，并会尽可能地避开公平的战斗。"
s_tiefling_traits=[[
<b c=tg>+2敏捷，+2智力，<c=tr>-2魅力：</c></b>泰夫林灵活机智，但天性怪异。

<b>技能熟练：</b>唬骗、躲藏检定有+2种族加值。]]
.."\n\n"..xs_lbl("s_res_cef_5")
.."\n\n".."<b>类法术能力：</b>每天可施展一次<t=@pwr_sp_dk_2 c=fc_b>黑暗术</t>，施法者等级等同角色等级。"-- 种族专长：泰夫林通过其职业等级获取专长。	Racial Feats: A tiefling gains feats according to its class levels.
s_tiefling_langs=[[
<b>初始语言：</b>通用语、炼狱语。
<b>额外语言：</b>龙语、矮人语、精灵语、侏儒语、地精语、半身人语、兽人语。

<c=twc>泰夫林说通用语和炼狱语。</c>
]]
s_tiefling_eds={
[race_ed_dd1]=[[
与凡人差异不多的魔裔是人类和魔族的后代。超凡的血腥特征使他们被世人恐惧和背弃。

由于造成他们出生的诅咒因缘常发生在数代之前，多数魔裔并不知晓自己的炼狱主人。血脉的污痕持续长久，常在出生时或不久后事与愿违地强力显现。

尽管有着魔族的容貌和下界的起源，魔裔与人类同样主宰着自己的命运；很多魔裔确实接受了黑暗血统并寄身于炼狱之力，其他人则拒绝自己的黑暗倾向。血脉的力量几乎令每个魔裔心中涌动的破坏和狂怒，但哪怕是魅魔的后裔也能成为圣者，深渊领主的子孙也会当上英雄。
]],
[race_ed_dd2]=[[
继承了恶魔，魔鬼或其他邪恶异界生物所玷污的人类血脉，泰夫林为它们怪异的外貌和习性为他人所非议，更使得这些魔裔只能在文明社会的阴暗角落和边缘区域挣扎求生。即使并非天生邪恶，它们成长的轨迹也往往印上被周围的“普通”人施加的种种痛苦。

大体上看他们的形象与人类无异，只有一些小小的区别会揭露泰夫林的怪异血缘。
]],
[race_ed_phy]=[[
没有两个魔裔长相相似；他们血脉中流淌的魔族之血各不相同，但都给他们带来了一些炼狱特征。

魔裔的外表是可能生有小角、尖尾、异色双眼的人类，可能长着獠牙、细翼、利爪，或者带有血腥、硫磺般的气味。

通常这些特征都可以追溯到魔裔的祖先身上；但即便如此，人类与魔族血统的混合也无常理可循、变化多端，使得魔裔外观奇妙，从脱俗美丽到令人作呕。
]],
[race_ed_btl]=s_tiefling_fav_cls,
[race_ed_soc]=[[
主物质位面的魔裔很少会建立自己的集落或要塞，而是居住在出生地周边的土地上。多数社会将魔裔看成怪物或诅咒，但在那些频繁与所召唤的魔族交流的文化中、尤其在崇拜恶魔、魔鬼或其他邪恶异界来客是合法行为的地区，魔裔可能更易为人接纳，甚至被视为来自魔族大君的祝福。

魔裔极少能遇到自己的同族，也因此常随人类亲族的文化习俗长大成人。在其他位面，魔裔会组成自己的聚落。但这些聚落也不太平——魔裔血统来源和哲学价值的多样性是冲突之源，各种派系的力量此消彼长，唯有最审时度势者才能占据优势。只有拥有共同血脉的魔裔之间，或决定摒弃自身自私、扭曲和邪恶天性的魔裔之间才能存在真正的相互信赖、同仇敌忾，并携手在同类中赢取立足之地。
]],
[race_ed_rel]=[[
魔裔饱受来自其他种族的歧视，常被看作魔族污秽、邪恶孽种、洪水猛兽以及异界诅咒。

文明种族常疏远或排斥他们，而蛮荒之民单纯地恐惧和拒绝他们，除非被迫屈从。但半精灵、半兽人以及——最不可思议的——神裔，会把他们看作亲人，认为他们同样是不被自己生身之地所容之人。

对于魔裔天性邪恶的普遍观点（虽是偏见但也许正是如此）使他们难以在多数主物质位面的文化中立足，除了那些常与外位面有跨界联系的国家。
]],
[race_ed_aln]=[[
尽管拥有魔族遗传并饱受偏见之苦，魔裔确实可能是任何阵营。很多魔裔屈服于扭曲了自己心智的黑暗欲望，听从了耳畔邪恶低语的诱惑；而那些坚定地拒绝自身起源、并主动和邪恶势力与外界偏见斗争的魔裔则有种种善行。然而，更多数的魔裔单纯地想在世上为自己找到安身立命之所，更倾向于从中立的视角审视自身和万物。

虽然很多生物觉得魔裔必然崇拜魔鬼和恶魔，他们的宗教观仍然如外貌般彼此迥异。魔裔个体可能尊崇所有神祗，但也有可能背弃一切宗教。那些因黑暗低语而堕落的魔裔会追随各种强大的魔族大君。
]],
[race_ed_adv]=[[
魔裔极少在称为家园的凡俗社会长期容身。而投身冒险生活也是一种逃避手段，他们希望为自己谋求更好的生活，来证明自己不被血统污点所束缚、或对畏惧和拒绝自己的世界本身加以惩戒。

魔裔是熟练的盗贼和强大的法师，并因特别的血统而能成为强有力的术士。那些与内在邪恶同调的魔裔常会成为下界力量的牧师。
]],-- 强大的法师和魔战士	magi
[race_ed_nam]=[[
<c=twa>常见男名：</c>
巴鲁（Baru），狄利萨（Dellisar），马德雷克（Maldrek），莫洛斯（Molos），萨文（Sarvin），舍利摩斯（Shoremoth），忒梅利斯（Temerith），沃棱（Voren），佐棱（Zoren）。

<c=twa>常见女名：</c>
阿莉萨（Allizsah），因德兰娜（Indranna），卡西卓（Kasidra），克拉娜（Kilarra），梅丽森（Mellisan），墨德兰（Mordren），妮莎（Nisha）。
]],
}-- 八路（Baru）


s_pc_elm_a="风元素裔"
s_pc_elm_a_c="这个苍白柔弱的女人，头发随着并不存在的微风而飘动，仿佛随时都可能消失于周围的薄雾之中。"
s_pc_elm_a_fav_cls="对诡计花招的热爱和天生善于摆脱困境的能力，使得风元素裔十分适合担当盗贼、小偷、间谍一类的角色。外表的害羞与柔弱为风元素裔的精明强干提供了完美的伪装，使得他们能不断的衡量对手，分析最有效的致胜之法。"
s_pc_elm_a_traits=[[
<b c=tg>+2敏捷，+2智力，<c=tr>-2体质：</c></b>风元素裔迅捷而富有洞察力，但是身体纤弱。]]
.."\n\n"..xs_lbl("s_res_e_5")
.."\n\n"..xs_lbl("s_res_spl_air_race_1")
.."\n\n"..[[
<b>技能熟练：</b>躲藏、聆听、易容、收集信息检定有+2种族加值。

<b>类法术能力：</b>可施展<t=@pwr_sp_litn c=fc_b>闪电束</t>、<t=@pwr_sp_displacement c=fc_b>移位术</t>、<t=@pwr_sp_cats_grace c=fc_b>猫之优雅</t>，每天各一次，施法者等级等同角色等级。
]]-- <b>无需呼吸：</b>风元素裔不需呼吸即能生存，所以他们对溺死、窒息、以及可造成类似效果的伤害免疫。-- <b>No Breathing: </b>Sylphs do not need to breathe to survive, so they are immune to drowning, suffocation, and damages that can cause similar effects.
s_pc_elm_a_langs=[[
<b>初始语言：</b>通用语、风族语。
<b>额外语言：</b>水族语、矮人语、精灵语、侏儒语、半身人语、火族语、土族语。

<c=twc>风元素裔说通用语和风族语。</c>
]]
s_pc_elm_a_d=[[
风元素裔是人类与大气系生物混血的后裔。

类似火、土和水元素裔，她们能操纵自身元素之力，从而成为强大的元素术士。

她们美丽纤细，并有窃听天赋。
]]
s_pc_elm_a_eds={
[race_ed_dd1]=[[
作为人类和巨灵之类气元素的后代，风元素裔极具好奇心却又害羞腼腆。

风元素裔融入人潮、脚步轻巧，从不被谁注意到，悄悄地侧耳倾听周遭人群的声音。她们将这种习惯称为“倾听流风”，对一些风元素裔而言已是呼吸般自然之举。

风元素裔依靠灵活机智和听风得来的情报回避危险。
]],
[race_ed_dd2]=[[
风元素裔是人类与风巨灵之类的气元素的后代。风元素裔虽然外表纤细柔弱，但她们瘦削的身体经常比看上去要坚韧的多。有不少风元素裔会使用一些小手段来掩盖自己身上的遗传特征，使自己混迹于人类群体中时不会被发觉真实的身份。只有十分了解他们的人有时才会注意到，这些风元素裔即使是在没有窗户的房间里，身边也会随时扬起微风。当风元素裔愤怒或情绪激动时，这种特征会变得明显，例如微风会变成围绕周身的旋风，或者将附近小物件吹落在地的气浪。许多风元素裔都会在他们苍白的肌肤上绘制图案复杂的苍蓝色螺旋状纹身。而最吸引人的是他们那曲折盘旋的长发，犹如一团活的云雾。

风元素裔生性害羞孤僻，他们经常巧妙的通过混入人群来避免碰到自己不愿见的人。尽管风元素裔通常不愿将自己卷入麻烦和纷争，但他们却天生对于其他人有着强烈的好奇心。这使得他们经常不遗余力的去刺探和偷听那些他们感兴趣的人（这种习惯被称为“倾听流风”）。对诡计花招的热爱和天生善于摆脱困境的能力，使得风元素裔十分适合担当盗贼、小偷、间谍一类的角色。外表的害羞与柔弱为风元素裔的精明强干提供了完美的伪装，使得他们能不断的衡量对手，分析最有效的致胜之法。
]],
[race_ed_phy]=[[
风元素裔外表纤细苍白，但她们瘦削的身体经常比看上去要坚韧。

很多风元素裔能轻易混进人类中，尽管她们体表多处漩涡状的苍蓝胎记揭示了其元素先祖。

风元素裔还有一些不易察觉的遗传特征，譬如随身扬起的微风等等。这些特征在风元素裔情绪激烈或愤怒时会变得明显起来，譬如令怒发冲冠的猎猎旋风，或能将小物体从架上扫落的热浪等。
]],
[race_ed_soc]=[[
风元素裔常有着人类双亲，并以人类的习俗被抚养长大。多数风元素裔不喜欢人类社会看待自己的异样目光，因此在到了年纪时离家出走司空见惯。但他们很少会背离文明之邦，而是去寻找能够不引人注目地安身（以及刺探）的城市。

偶然悄悄看到同族的风元素裔会被对方深深吸引，尽其所能地了解和调查对方。只有在充分地权衡利弊、并对各种反应都做好应对预案后，风元素裔才会主动现身于他人面前。

当两个风元素裔少有地邂逅在某个社群中时，接下去往往是一系列猫鼠追逐的游戏，伴随着彼此试探的闪转腾挪和回旋舞蹈、以求占据上风。以这种方式相遇的风元素裔通常后来会如胶似漆或不共戴天。
]],
[race_ed_rel]=[[
风元素裔以观察其他种族为乐，但不大愿意接触其中大多数。

出于共同的疏离感，风元素裔可以和精灵建立某种程度的联系，不过经常由于敏感的精灵觉得隐私被侵犯而使关系破裂。

矮人很不信任风元素裔，觉得她们轻浮而不可靠。

她们和半身人倒是至交好友，感服于这些小家伙的勇气、以及扬长避短的多彩技巧。

风元素裔觉得喜怒无常的火元素裔太烦人，而沉闷的土元素裔则过于无趣。
]],
[race_ed_aln]=[[
风元素裔不把律法和传统当回事，这些东西往往禁止她们最大的爱好——回避社会和偷偷摸摸。这并不意味着风元素裔站在法律对立面，她们只不过用最为可行的权宜之计、来达到自己合法或非法的目标而已。因此多数风元素裔是中立阵营的。

风元素天性易被秘闻吸引，以及专注于秘密、旅行和知识的神祇。
]],
[race_ed_adv]=[[
打破沙锅问到底的天性驱使很多风元素裔踏上冒险之旅。

追寻着秘迹的风元素裔在寻获每一条证据、走遍每一个角落、解决每一件麻烦之前是不会满足的。

这些风元素裔也因插足他人事务而为自己树敌不少，并常用自己的盗贼天赋或魔法技巧来保护自己。
]],
[race_ed_nam]=[[
<c=twa>常见男名：</c>
阿卡什（Akaash），艾丹（Eydan），哈努恩（Hanuun），西瓦尔（Siival），瓦萨姆（Vasaam）。

<c=twa>常见女名：</c>
伊娜穆（Inam），姬雅（Keeya），莉希（Lissi），娜娃（Nava），拉达雅（Radaya），忒娜（Tena）。
]],
}--【译注：秘密之神－诺格巴（Norgorber，中立邪恶）；旅行女神－黛丝娜（Desna，混乱善良）；知识之神－义洛理（Irori，秩序中立）。整体上相当平衡嗯。】


s_pc_elm_f="火元素裔"
s_pc_elm_f_c="这个有着火焰般皮肤的健壮男子，头发尤如飘动的赤炎，前额上长着斑驳的双角。"
s_pc_elm_f_fav_cls="常因纵火而被城市驱逐，火元素裔中常出强力的火术士，以及与其他种族迥异的能够操纵火焰的战士。"
s_pc_elm_f_traits=[[
<b c=tg>+2敏捷，+2魅力，<c=tr>-2感知：</c></b>火元素裔迅捷而又充满热情，但同时也很鲁莽并且带有破坏欲。]]
.."\n\n"..xs_lbl("s_res_f_5")
.."\n\n"..xs_lbl("s_res_spl_fire_race_1")
.."\n\n"..[[
<b>技能熟练：</b>跳跃、翻滚、威吓、唬骗检定有+2种族加值。

<b>类法术能力：</b>可施展<t=@pwr_sp_burning_hands c=fc_b>燃烧之手</t>、<t=@pwr_sp_fire_ball c=fc_b>火球术</t>、<t=@pwr_sp_rage2 c=fc_b>狂暴术</t>，每天各一次，施法者等级等同角色等级。
]]--控火术（Sp）：火元素裔可每日一次在周围10尺内产生1道非魔法火焰，亮度从煤燃烧的昏暗火光到如同日光的白亮，照明半径加倍，这种能力不会产生热量，也不需要火源，可维持5分钟，如同等5级术士施展。
s_pc_elm_f_langs=[[
<b>初始语言：</b>通用语、火族语。
<b>额外语言：</b>水族语、风族语、矮人语、精灵语、侏儒语、半身人语、土族语。

<c=twc>火元素裔说通用语和火族语。</c>
]]
s_pc_elm_f_d=[[
火元素裔是凡人与火位面奇妙生物的后代。

他们的体貌特征和性格个性往往令其激烈血缘得以彰显，他们无情、独立而又狂妄。

常因纵火而被城市驱逐，火元素裔中常出强力的火术士，以及与其他种族迥异的能够操纵火焰的战士。
]]
s_pc_elm_f_eds={
[race_ed_dd1]=[[
火元素裔是以火巨灵等元素之火为先祖的人类，是富于激情和喜怒无常的种族。

没有火元素裔会安于一成不变的生活；他们如同野火般必须时刻浮动、并燃烧殆尽。火元素裔不仅爱慕炽焰，他们的人格本来就是火焰的化身：激烈燃烧，变幻无常，不知怜悯。
]],
[race_ed_dd2]=[[
火元素裔是以元素之火（例如火巨灵）为祖先的人类。火元素裔都长着一对尖耳朵，额头上有着红色或斑点的双角，头发如火焰般飘动。

所有的火元素裔几乎都有着纵火狂的潜质，他们崇拜任何形式的火焰。他们往往性格冲动，行事鲁莽，倾向于在任何冲突中都先发制人——这样的特点使他们往往能够得以生存却很难交到朋友。在冒险的时候。火元素裔一般会去找那种比较软弱，可以通过威吓对其进行指挥的随从，或者那种对他人比较疏远，容易抵消火元素裔冲动天性的伙伴。
]],
[race_ed_phy]=[[
火元素裔的外貌根据先祖不同而变化多端。多数有尖耳朵，红色或斑驳的角，头发如同火焰般飘动。有些人的肤色如同精炼黄铜，或者四肢覆盖着焦炭般的鳞片。

火元素裔喜欢暴露和浮夸的红、橙等暖色调服饰，再用俗艳的首饰加以装点。
]],
[race_ed_soc]=[[
火元素裔多出生在人类社群中，并很少结成自己的社区。

在城市长大的火元素裔几乎都在成年前被监禁或放逐；他们中的多数由于头脑发热或太过特立独行而无法融入文明社会，纵火狂的嗜好也使他们不受当局待见。

在游牧或部落社会出生的火元素裔要好得多，因为他们探索和征服周遭的本能可以为自己轻易地赢取领导者的地位。
]],
[race_ed_rel]=[[
即便天性最纯良的火元素裔也不免将他人视为工具，因此他们与那些可以魅惑、或可以威压的种族相处得最好。

半精灵和侏儒时常发现自己置身于火元素裔的阴谋中，而半身人、半兽人和矮人则常对火元素裔的支配天性感到愠怒。

意外的是火元素裔有时会和精灵建立格外亲密的羁绊，精灵疏远他人的天性似乎抵消了火元素裔的冲动本质。

多数火元素裔拒绝接触风元素裔，不过倒是和其他元素裔种族相安无事。
]],
[race_ed_aln]=[[
火元素裔是性格分明之人——激烈，独立，傲慢而又难伺候。他们经常因道德缺陷而受到指控，但他们的捣蛋天性很少出于真正恶意的动机。火元素裔通常是秩序中立或混乱中立阵营，也有少数绝对中立。

多数火元素裔缺少遵从神祇教诲的心态，也讨厌受到宗教组织的束缚。当火元素裔真心崇拜神祇之时（通常是与火相关的），他们会展现出狂热教徒和虔诚信众的一面。
]],
[race_ed_adv]=[[
火元素裔会为追求刺激和测试抗敌技巧而踏上冒险之道，但绝大多数情况下是为追逐力量而冒险。

当火元素裔专注于某项任务时，他们无畏地进取，绝不停步思量前路有多危险。当终于因莽撞而涉险之时，火元素裔常依靠术士或吟游诗人的魔法来击退麻烦。
]],
[race_ed_nam]=[[
<c=twa>常见男名：</c>
阿甲（Aja），德纳特（Denat），艾菲特（Efit），厄郎（Elum），亚力（Jalij），马切（Maqej），乌拉（Urah）。

<c=twa>常见女名：</c>
阿拉伊（Alayi），艾特娃（Etwa），玛刊（Maqan），卡莉（Qari），萨米（Sami），泽塔雅（Zetaya）。
]],
}


s_pc_elm_w="水元素裔"
s_pc_elm_w_c="这个蓝肤蓝发的男人举止优雅，他长着鱼鳍状的双耳和带蹼的手足。"
s_pc_elm_w_fav_cls="水元素裔对水的亲和让她们能够成为特别优秀的德鲁伊。"--..add_hr("水元素裔的天赋职业暂由德鲁伊改为牧师。")..add_hr("Changed undines' favored class from Druid to Cleric temporarily.")..add_hr("Cambiata temporaneamente la classe preferita degli ondini da Ranger a Combattente.")
s_pc_elm_w_traits=[[
<b c=tg>+2敏捷，+2感知，<c=tr>-2力量：</c></b>水元素裔兼具着敏捷以及感知力，但是她们往往选择顺应潮流而非以力较力。]]
.."\n\n"..xs_lbl("s_res_c_5")
.."\n\n"..xs_lbl("s_res_spl_water_race_1")
.."\n\n"..[[
<b>技能熟练：</b>游泳、估价、医疗、交涉检定有+2种族加值。

<b>类法术能力：</b>可施展<t=@pwr_sp_heal c=fc_b>治疗术</t>、<t=@pwr_sp_bless c=fc_b>祝福术</t>、<t=@pwr_sp_aid c=fc_b>援助术</t>，每天各一次，施法者等级等同角色等级。
]]
s_pc_elm_w_langs=[[
<b>初始语言：</b>通用语、水族语。
<b>额外语言：</b>风族语、矮人语、精灵语、侏儒语、半身人语、火族语、土族语。

<c=twc>水元素裔说通用语和水族语。</c>
]]
s_pc_elm_w_d=[[
水元素裔和她们的土、风、火族表亲相似，是人类与元素位面的混血后代。

她们则是水元素的末裔，在陆上和水中同样优雅得体。

水元素裔适应并能抵御寒冷，同时对水系魔法亲和性甚高。
]]
s_pc_elm_w_eds={
[race_ed_dd1]=[[
水元素裔是可将祖先溯至水位面生物的人类。水元素裔的每一块肌肤都是湖泊、海洋的拟似，即便一眼就能看出她们的先祖血脉。无论亲族是水灵或海妖，所有的水元素裔按先祖出身来自我区分。她们将个体差异当作天赋赐予，并探索着自己特殊血脉的超自然升华。

水元素裔是面无惧色的骄傲种族。天性善良的她们在与同族相处时爱开玩笑，而和外族打交道时相对要保守和严肃一些。她们情绪自控的能力极为出色，能够在瞬息之间让心态在冷静与狂暴的边缘自如游走。有些人可能会觉得她们喜怒无常，其实水元素裔只是感情相较他族稍微夸张了一点而已。她们当然不是神经病，不会无缘无故地陷入愤慨、兴奋或是其他情绪中。水元素裔的亲密友人有时会发现她们占有欲过强，不过她们对于珍视之人确实有着强烈的保护欲。

水元素裔通常在温暖气候下临水而居。虽然生活在陆地上，她们喜欢在水里待很长时间。多数水元素裔出于这个理由穿得很少，通常只穿戴足以防护严酷气候的服装，并多赤足。她们尽量避免在颈部佩戴首饰，并将头发盘扎成结。她们会防止头发或其他物件在游泳时成为妨碍。类似地，习练武技的水元素裔也会选择那些在陆上、水中同样顺手的兵器。
]],
[race_ed_dd2]=[[
水元素裔是可将祖先溯至水元素相关生物（如水巨灵）的人类。

这种与水元素位面的深刻联系，通过水元素裔犹如混合了湖泊与海洋的肤色，可以很明显的看出他们与水元素位面的联系——水元素裔都有着清澈的蓝色眼睛，他们的皮肤和头发颜色多变，从苍青到深蓝、再到水绿。
]],
[race_ed_phy]=[[
水元素裔的肤色变化多端，从苍青到深蓝、再到水绿。水元素裔浓密的直发颜色会和肤色接近，但比肤色更深一些。她们全都有着清澈的蓝眼睛。

水元素裔生理上而言最接近人类，因此身高体型也如同人类般彼此迥异。

除了肤色，她们最大的种族特征就是鱼鳍状的耳朵和有蹼的手足。
]],
[race_ed_soc]=[[
水元素裔自视为独一无二的种族，并能够相互繁衍。虽然能和人类诞下后代，她们还是倾向于种内婚配，并在水源附近组成小小的隐居社群、或游牧于水畔。水元素裔社群内部的通婚很普遍，并共同抚养小孩。

典型的水元素裔社群在小评议会的指导下生活，并在公共事务上寻求意见一致。评议会可以长久地存续，不过当社群对其某位成员的表现不满时可以弹劾其下台。

水元素裔文化的宗教多样性相当大，这也是不同集落之间先祖出身各异的结果之一。值得一提的是，同一个集落里的水元素裔也未必有着共同祖先，而她们也可能和来自其他社群的水元素裔结姻。
]],
[race_ed_rel]=[[
水元素裔对任何种族都不抱有偏爱或歧视。她们的社群依赖于商贸，这给予她们和广泛的外族相互接触的机会。她们也不介意在其他种族的集落里定居，只要对方能够同等地尊重水元素裔和邻近的水域。即便这种情况下，一个水元素裔社群还是会尽量保持自主权。

水元素裔与精灵和侏儒的关系格外融洽，这些种族往往身为森林中湖泊和溪流的守护者。类似地，她们也乐于同善良或中立水生类人生物打交道，因为彼此有着共同的偏好。她们会和人类以及矮人交易钢铁和布料等资源。
]],
[race_ed_aln]=[[
多数水元素裔是中立的。她们的原则在于维护同族人民的福祉，因此道德规范也常专注于社群整体。这种中立的视角也让她们能和广泛的外族之间展开贸易来往。

尽管并无宗教狂热，水元素裔和超自然祖先以及“水”本身之间都有着强烈的精神联结。那些追求超脱凡俗之道的水元素裔几乎全都会崇拜自己先祖的神祇，或是神职、权能中和水有关的神祇。
]],
[race_ed_adv]=[[
某些时候，水元素裔会离开族人、踏上冒险之旅。如同水一般，很多水元素裔只是单纯地喜欢流动，而冒险给予了她们最合适不过的旅行借口。

有些人的冒险理由没有如此光彩，譬如因为在社群内犯下的罪行而遭流放。没有更多选择的被放逐者只能冒险和游荡，期盼着能为自己找到新的家园。

水元素裔对水的亲和让她们能够成为特别优秀的德鲁伊，而水元素裔术士则多为深洋血统。
]],-- 深洋血统（Aquatic, APG）
[race_ed_nam]=[[
<c=twa>常见男名：</c>
阿温（Aven），达拉克（Dharak），基辅（Ghiv），雅玛士（Jamash），马考（Maakor），翁狄尔（Ondir），拉迪（Radid），西拉达兹（Shiradahz）。

<c=twa>常见女名：</c>
阿芙珈拉（Afzara），芭拉（Baarah），卡拉（Calah），伊莉亚妮（Iryani），玛琳（Maarin），妮让（Nylgune），帕芮（Pari），拉达蓓（Radabeh），厄妲娜（Urdahna）。
]],
}


s_pc_elm_e="土元素裔"
s_pc_elm_e_c="这个高大的战士沉稳而坚定，如凿刻般棱角分明的面孔使她看起来就像一个有了生命的雕像。"
s_pc_elm_e_fav_cls="由于天生拥有强壮身躯和自律精神，土元素裔是优秀的武僧和战士。"
s_pc_elm_e_traits=[[
<b c=tg>+2力量，+2感知，<c=tr>-2魅力：</c></b>土元素裔强壮，可靠，沉稳并且恬淡寡欲。]]
.."\n\n"..xs_lbl("s_res_a_5")
.."\n\n"..xs_lbl("s_res_spl_earth_race_1")
.."\n\n"..[[
<b>技能熟练：</b>攀爬、侦察、生存、专注检定有+2种族加值。

<b>类法术能力：</b>可施展<t=@pwr_sp_shield_other c=fc_b>护卫他人</t>、<t=@pwr_sp_stoneskin c=fc_b>石肤术</t>、<t=@pwr_sp_bears_endurance c=fc_b>熊之坚韧</t>，每天各一次，施法者等级等同角色等级。
]]
s_pc_elm_e_langs=[[
<b>初始语言：</b>通用语、土族语。
<b>额外语言：</b>水族语、风族语、矮人语、精灵语、侏儒语、半身人语、火族语、地底通用语。

<c=twc>土元素裔说通用语和土族语。</c>
]]
s_pc_elm_e_d=[[
土元素裔的祖先是混有土元素位面血统的人类，他们同磐石一样强固。

经常顽固而又坚定，他们不屈的天性令自己很难与矮人以外的大多种族友好相处。

土元素裔能成为优异的武士或术士，能够操控大地与后土的原生之力。
]]
s_pc_elm_e_eds={
[race_ed_dd1]=[[
土元素裔是祖先曾与大地元素（经常是土巨灵）有过接触的人类后裔。

坚忍克己、爱好冥思，土元素裔是不易动摇的种族，在行动时却又不可阻挡。由于出世的天性，他们对多数世人而言仍是神秘的存在；但那些在与世隔绝的世外桃源找到土元素裔的旅者，会发现他们是沉稳、可靠、保护性强的朋友。
]],
[race_ed_dd2]=[[
土元素裔是祖先曾与大地元素（经常是土巨灵）有过接触的人类后裔。土元素裔体格强壮坚实，通常他们偏好于穿着和大地色调一致的衣物，这可以搭配他们那特殊的肤色和发色（通常是如石斑一样的灰、棕、黑或白色）。少数情况下，有的土元素裔元素血脉的特征会表现的极其明显，他们的皮肤和头发会长出矿石晶簇，让旁人一眼就能认出他们的来历。

土元素裔性情沉稳内敛，他们很少动怒，但在战斗中依然十分可怕。在团队中，他们倾向于担当安静、可靠、为大家提供保护的角色。
]],
[race_ed_phy]=[[
土元素裔强壮而又坚固，皮肤和毛发都呈黑、褐、棕、灰或白等石斑的颜色。

尽管所有土元素裔的外表朴实厚重，少数特征还是体现了他们的元素遗传——玛瑙般的皮肤，磐石般虬结的块状肌肉，宝石般闪耀的双眼，水晶丛般的头发……等等。

他们衣着简朴，穿着适于活动的衣服并用鲜花、纯色宝石、以及其它从天然到手工的精致小物件加以装点。
]],
[race_ed_soc]=[[
作为人类的小小分支，土元素裔并没有自己的社会组织。多数土元素裔都在人类社区中长大成人，从父母处学习风土人情。

成年的土元素裔相较其他种族而言，有着强烈的避世隐居的倾向。少有土元素裔能适应喧嚣的都市生活，他们更愿意在人迹罕至的万仞峰顶、绝世独立的的理想乡中静思度日。

与人类亲近的土元素裔经常会加入城市守卫队，或寻找其他能够以责任感为社区效命的岗位。
]],
[race_ed_rel]=[[
土元素裔与矮人关系很好，因为两者共性甚多。

他们觉得侏儒太过怪异、半身人自以为是，大体上避免和他们接触。

土元素裔高兴和半兽人、半精灵交往，尽管有着不可避免的人格冲突，毕竟可以在彼此之间同有的人类血脉中找到羁绊。

土元素裔和其他元素裔种族并无深交，也非仇敌。
]],
[race_ed_aln]=[[
土元素裔可能是最为顽固的种族，一旦确定路线，将会静静地拒绝任何打扰。

土元素裔会奋不顾身地保护朋友们，但不太在乎熟人之外的世间善恶。因此多数土元素裔秩序中立。

这些大地之灵易受宗教感召。他们喜欢隐修教会安静、避世的生活，并大多崇拜那些土系、或与自然相关的神祇。
]],
[race_ed_adv]=[[
土元素裔一开始是犹豫不决的冒险者。他们不喜欢离乡背井，也不太善于处理各种新体验。往往是有外力迫使土元素裔展开行动，譬如威胁他们的故乡、生命或是朋友等。当最初遭受的威胁解除时，土元素裔常会发现自己已经习惯了冒险生活，并会在这条道路上奉献余生。

由于天生拥有强壮身躯和自律精神，土元素裔是优秀的武僧和战士。
]],
[race_ed_nam]=[[
<c=twa>常见男名：</c>
安达南（Andanan），吉达乌（Jeydavu），蒙提斯（Mentys），欧列特（Oret），西桑丹（Sithundan），尔塔（Urtar）。

<c=twa>常见女名：</c>
贝萨娜（Besthana），爱莎涅（Echane），迦提亚拉（Ghatiyara），伊利瑟（Irice），奈瑟涅（Nysene），帕谢（Pashe）。
]],
}-- 视既感（Jeydavu）


s_heat="高温"
s_heat_d="火矮人的身体非常炽热，因此他们的徒手攻击会造成额外的火焰伤害。他们的金属武器也会传导这种高温。"

s_azer="火矮人"
s_azer_c="高热扭曲了这个矮胖的黄铜色皮肤的人型生物周围的空气。他的头部和肩部都闪耀着一串火焰。"
s_azer_fav_cls="火矮人可以把高温传导到金属武器或工具上，所以他们几乎不使用非金属武器，并且通常在战斗中倾向于近战而非远程攻击。"
s_azer_traits=[[
<b c=tg>+2力量，+2敏捷，+2体质，+2智力，+2感知，<c=tr>-2魅力：</c></b>除了不太友善而且沉默寡言，火矮人在各方面都表现不俗。

<b>种族生命骰：</b>火矮人初始拥有2个异界生物等级，给予它2d8生命骰。

<b>种族技能：</b>火矮人的异界生物等级给予它5 x (8 + 智力调整值)的技能点数。其本职技能为攀爬、跳跃、躲藏、估价、手艺、搜索、侦察、聆听。

<b>种族专长：</b>火矮人的异界生物等级给予它1个专长。

<b>防御：</b>+6天生防御加值。

<b>武器和盔甲擅长：</b>擅长简易武器、战锤、轻甲、中甲、盾牌。

<b>特殊能力：</b><t=@pwr_heat c=fc_b>高温</t>，<t=@pwr_imm_f c=fc_b>火焰免疫</t>，<t=@pwr_vul_c c=fc_b>寒冷易伤</t>，<t=@pwr_spl_res_13 c=fc_b>法术抗力13+</t>。
]]-- +2的基本攻击加值，以及强韧+3、反射+3和意志+3的基本豁免加值。a base attack bonus of +2, and base saving throw bonuses of Fort +3, Ref +3, and Will +3.
s_azer_langs=[[
<b>初始语言：</b>通用语、火族语。
<b>额外语言：</b>深渊语、水族语、风族语、天界语、炼狱语、土族语。

<c=twc>火矮人说火族语和通用语。</c>
]]
s_azer_d=[[
火矮人是出生于火元素位面的类矮人生物。他们穿着由黄铜、青铜或赤铜打造成的短裙，并且说火族语和通用语。火矮人在不熟悉的人眼中看起来都差不多。它们有4尺高，但是重200磅。

火矮人生活在一个所有人都恪尽职守的社会中。它们在青铜或黄铜要塞中辛勤劳作，为了即将爆发的和火巨灵之间的漫长战争而时刻准备着。

传奇的黄铜之城据火矮人自称有超过五十万人口。大多数不幸的火矮人作为它们火巨灵主人的奴隶而生活。

除了黄铜之城，其他火矮人们自由地生活着，经常在异界的大城市中制造工艺品、做买卖或开酒馆。
]]-- 火矮人是火元素位面上骄傲而勤劳的种族	A proud and hardworking race from the Plane of Fire
s_azer_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
]],
[race_ed_btl]=[[
火矮人在战斗中使用平头矛或者制作精良的战锤。在空手时，他们会试图擒抱对手。

火矮人可以把高温传导到金属武器或工具上，所以他们几乎不使用非金属武器，并且通常在战斗中倾向于近战而非远程攻击。

尽管不太友善而且沉默寡言，但是火矮人很少挑起争斗，除非对方带着他们所喜爱的宝石。

如果受到了威胁，那么火矮人会奋战到底，但是他们了解俘虏敌人所带来的价值。火矮人经常抓获俘虏，然后把它们带回要塞中，强迫它们长年累月地劳动。
]],
[race_ed_soc]=[[
火矮人生活在一个所有人都恪尽职守的社会中。火矮人生来就被赋予特定的角色，通常继承自它们父母，而他终其一生都必须履行他的职责。

种姓制度让火矮人的社会秩序更加牢固。贵族的统治毫无疑议，穿着者象征着它们种姓的黄铜装饰的短裙，而商人和资本家则穿着厚实的青铜，工人阶级则被指定穿着红铜，他们主要是仆人、工匠和劳动者。

传奇的黄铜之城据火矮人自称有超过五十万人口。大多数不幸的火矮人作为它们火巨灵主人的奴隶而生活。

火矮人就算被当做奴隶也毫无疑问地履行着它们的职责，宁愿等到契约结束或它们的主人死掉或被推翻之时。对秩序的奉献深深地烙印在这个种族上，已经达到了一些火矮人奴隶能被选出作为监工来看管其他同胞的程度。

除了黄铜之城，其他火矮人们自由地生活着，经常在异界的大城市中制造工艺品、做买卖或开酒馆。
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}

s_genie			="巨灵"
s_genie_d		=[[巨灵是居住在元素位面的长得像人类的生物。它们素以其强壮，狡诈及善用幻术而闻名。

巨灵喜欢以策略和计谋战胜敌人。如果逃跑会使它们活下来他日再战的话，它们也不会宁死不屈。如果被困住，它们会提出给予宝物或提供某种回报来换取其生命和自由。]]

