s_elm_a2		="风元素"	s_elm_a2_d=[[风元素会说风族语，但是它们很少开口。

<b c=tw>战斗</b>
风元素极快的速度使得它们在辽阔的战场或长时间空战中获得巨大的优势。

<b c=tw>风元素体型</b>
<b c=tw>元素	高度	重量</b>
小型	4尺	1磅
中型	8尺	2磅
大型	16尺	4磅
超大型	32尺	8磅
巨型	36尺	10磅
长老	40尺	12磅]]-- 通称k用xx_a2 避免xx_a_m冲突

s_elm_e2		="土元素"	s_elm_e2_d=[[被召唤到物质界时，土元素由各种不同类型的泥土，石头，贵金属和宝石组成。

土元素会说土族语，但是它们很少开口。

<b c=tw>战斗</b>
尽管土元素移动缓慢，但它是无情的对手。它能在坚固的地表和岩石中行走，就好像人类在地面行走一样容易。它不会游泳，如果遇到水域时，只能绕过去或者从水下的土地中穿越。土元素可以在水底移动但是它们不喜欢那么做。

<b c=tw>土元素体型</b>
<b c=tw>元素	高度	重量</b>
小型	4尺	80磅
中型	8尺	750磅
大型	16尺	6000磅
超大型	32尺	48000磅
巨型	36尺	54000磅
长老	40尺	60000磅]]

s_elm_f2		="火元素"	s_elm_f2_d=[[火元素无法进入水或任何不可燃的液体之中。任何水域对火元素来说都是不可跨越的障碍，除非它们能跨越或跳跃过去。

火元素会说火族语，但是它们很少开口。

<b c=tw>战斗</b>
火元素是个凶猛的对手，它会直接而野蛮地攻击它的敌人。将物质界的生物和物品烧成灰烬是它的乐趣。

<b c=tw>火元素体型</b>
<b c=tw>元素	高度	重量	烧灼DC</b>
小型	4尺	1磅	11
中型	8尺	2磅	14
大型	16尺	4磅	17
超大型	32尺	8磅	22
巨型	36尺	10磅	24
长老	40尺	12磅	26]]

s_elm_w2		="水元素"	s_elm_w2_d=[[水元素与形成它们的水域之间的距离不能超过180尺。

水元素会说水族语，但是它们很少开口。

<b c=tw>战斗</b>
水元素喜欢在大面积的水域中作战，这样它就可以在波浪后面消失并出其不意地出现在其对手身后。

<b c=tw>水元素体型</b>
<b c=tw>元素	高度	重量</b>
小型	4尺	34磅
中型	8尺	280磅
大型	16尺	2250磅
超大型	32尺	18000磅
巨型	36尺	21000磅
长老	40尺	24000磅]]

s_air_mastery	="天空熟悉"	s_air_mastery_d		="飞行中的生物在对抗风元素时其攻击和伤害检定上会受到-1的罚值。"
s_earth_mastery	="大地熟悉"	s_earth_mastery_d	="当土元素和它的敌人都能接触地表时，它在攻击和伤害检定上可获得+1的加值。如果对手在空中或者水里，则土元素在上述检定上会受到-4的罚值。"-- （列表中未包含上述数据。） (These modifiers are not included in the statistics block.)
s_water_mastery	="水域熟悉"	s_water_mastery_d	="当水元素和它的对手都能接触到水时，它在攻击和伤害检定上可获得+1的加值。如果水元素或其对手在陆地上，则水元素在上述检定上会受到-4的罚值。\n\n水元素对穿越其行进路线的船只会造成严重的威胁。水元素可以轻易地翻转小型船只（水元素每生命骰相当于船只5尺长度）并让较大型船只停驶（水元素每生命骰相当于船只10尺长度）。即使大型船只（水元素每生命骰相当于船只20尺长度）也会被减慢到一半的速度。"-- ...
s_earth_push	="推进"		s_earth_push_d		="土元素展开冲撞动作时不会引发借机攻击。大地熟悉提供的战斗调整值在土元素进行战技检定时也适用。"-- 力量检定 opposed Strength
s_earth_glide	="遁地"		s_earth_glide_d		="土元素可以如鱼在水中游泳一样在石头，泥土或除了金属之外任何类型的土地内部穿行。它掘穴时不会在身后留下任何隧道或洞穴，也不会产生细微震动或任何表明它的存在的迹象。"-- 施展在正在掘穴中的土元素所在区域上的移土术会将它向后抛出30尺，除非成功通过一个DC15的强韧豁免检定它还会被震慑1轮。 A move earth spell cast on an area containing a burrowing earth elemental flings the elemental back 30 feet, stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save.
s_fire_burn		="烧灼"		s_fire_burn_d		="火元素的挥击攻击能制造出钝击伤害外加燃烧的身体所带来的火焰伤害。被火元素的挥击攻击击中的对手必须要通过一个反射豁免检定（DC = 10 + 火元素HD/2 + 体质调整值）否则身上就会着火燃烧1d4轮。着火的生物可以通过一个移动动作来扑灭火焰。\n\n使用其天生武器或者徒手攻击命中火元素的生物会如被火元素击中一样受到火焰伤害，而且它们必须通过反射豁免检定否则也会浑身着火。"-- 而异 (见下表) (see the table below)	 该豁免检定DC因火元素体型而异。	该豁免检定DC基于体质调整值。	The save DC varies with the elemental’s size.	The save DC is Constitution- based.
s_water_drench	="浸湿"		s_water_drench_d	="水元素的触摸可以熄灭火把，萤火，暴露在外的灯火，以及其他大型或更小的非魔法且无保护的火焰。水元素可以通过触摸解除魔法火焰，如同解除魔法法术一样（施法等级等于水元素生命骰）。"
s_water_skls	="技能"		s_water_skls_d		="在进行游泳检定来做出特殊动作或躲避危险时水元素可获得+8的种族加值。它可在游泳检定中总是取10，即使注意力被分散或处于危险时也一样。它可在游泳中使用奔跑动作，但是只能直线前进。"
s_air_whirlwind	="旋风"		s_air_whirlwind_d	=""
s_water_vortex	="旋涡"		s_water_vortex_d	=""
--[[
s_air_whirlwind="旋风" s_air_whirlwind_d=风元素每10分钟可以将自己转变成一道旋风，每2个生命骰可使风元素保持在旋风状态1轮。在这种形态下，风元素可以其飞行速度在空中或沿着物质表面移动。

旋风的基部有5尺宽，顶端最大可到30尺宽，高度最大可到50尺，具体尺寸取决于风元素的体型。风元素可以控制旋风的准确高度，但是旋风最低也要有10尺高。

处于旋风形态下的风元素的行动不会引发借机攻击，即使它进入其他生物占据的空间也不会。如果其他生物接触到或进入旋风，或者风元素移动进或穿越该生物占据的空间，那么该生物就会被卷入其中。

体型比风元素小一级或更多的生物被卷入旋风时可能会受到伤害 (详情见下表)，也可能会被升到空中。受影响的生物在接触旋风时必须通过一个反射豁免检定，否则会将会受到表中列出的伤害。该生物也必须要通过第二次反射豁免检定，否则整个身体会被卷入其中并且被强风悬吊在半空中，每轮将会自动受到表中列出的伤害。会飞的生物每轮都可进行一次反射豁免检定以逃脱旋风。生物仍会受到伤害但是如果豁免检定成功将会脱离旋风。对抗旋风的豁免检定DC因风元素体型而异 (见下表)。该豁免检定DC基于力量调整值。

被卷入旋风的生物除了被风元素带着移动或尝试逃脱之外不能移动。被卷入旋风中的生物可以正常的做其他动作，但是必须在专注技能检定中获得成功 (DC 15 + 法术等级)才能施展法术。被卷入旋风中的生物敏捷受到-4的罚值，在攻击检定上受到-2的罚值。风元素同时能困住的生物数量取决于其旋风的体积。

风元素随时都能将其卷入的生物抛出来，它们会被丢到旋风目前的位置。被召唤来的风元素在返回所属位面之前总会将被其困住得生物丢出来。

如果旋风的基部接触到地面的话，将会产生一片旋转的沙砾云。这沙砾云以风元素为中心，直径等于旋风高度的一半。沙砾云会遮挡5尺距离外的所有视觉能力，包括黑暗视觉。5尺之外的生物获得隐蔽，更远的生物则获得全隐蔽。被沙砾云笼罩的生物必须通过一个专注技能检定 (DC 15 + 法术等级)才能施展法术。

旋风形态下的风元素不能进行挥击攻击，同时也不会威胁到其身边的区域。

s_air_whirlwind="Whirlwind" s_air_whirlwind_d=The elemental can transform itself into a whirlwind once every 10 minutes and remain in that form for up to 1 round for every 2 HD it has. In this form, the elemental can move through the air or along a surface at its fly speed.

The whirlwind is 5 feet wide at the base, up to 30 feet wide at the top, and up to 50 feet tall, depending on the elemental’s size. The elemental controls the exact height, but it must be at least 10 feet.

The elemental’s movement while in whirlwind form does not provoke attacks of opportunity, even if the elemental enters the space another creature occupies. Another creature might be caught in the whirlwind if it touches or enters the whirlwind, or if the elemental moves into or through the creature’s space.

Creatures one or more size categories smaller than the elemental might take damage when caught in the whirlwind (see the table below for details) and may be lifted into the air. An affected creature must succeed on a Reflex save when it comes into contact with the whirlwind or take the indicated damage. It must also succeed on a second Reflex save or be picked up bodily and held suspended in the powerful winds, automatically taking the indicated damage each round. A creature that can fly is allowed a Reflex save each round to escape the whirlwind. The creature still takes damage but can leave if the save is successful. The DC for saves against the whirlwind’s effects varies with the elemental’s size (see the table). The save DC is Strength based.

Creatures trapped in the whirlwind cannot move except to go where the elemental carries them or to escape the whirlwind. Creatures caught in the whirlwind can otherwise act normally, but must succeed on a Concentration check (DC 15 + spell level) to cast a spell. Creatures caught in the whirlwind take a –4 penalty to Dexterity and a –2 penalty on attack rolls. The elemental can have only as many creatures trapped inside the whirlwind at one time as will fit inside the whirlwind’s volume.

The elemental can eject any carried creatures whenever it wishes, depositing them wherever the whirlwind happens to be. A summoned elemental always ejects trapped creatures before returning to its home plane.

If the whirlwind’s base touches the ground, it creates a swirling cloud of debris. This cloud is centered on the elemental and has a diameter equal to half the whirlwind’s height. The cloud obscures all vision, including darkvision, beyond 5 feet. Creatures 5 feet away have concealment, while those farther away have total concealment. Those caught in the cloud must succeed on a Concentration check (DC 15 + spell level) to cast a spell.

An elemental in whirlwind form cannot make slam attacks and does not threaten the area around it.

s_water_vortex="旋涡" s_water_vortex_d=水元素只要在水中，每10分钟就可以将自己转变成一道旋涡，每2个生命骰可使水元素保持在旋涡状态1轮。在这种形态下，水元素可以其游泳速度在水中或沿着水底移动。旋涡的基部有5尺宽，顶端最大可到30尺宽，高度在10尺以上，具体尺寸取决于水元素的体型。水元素可以控制旋涡的准确高度，但是最低也要有10尺高。

处于旋涡形态下的水元素的行动不会引发借机攻击，即使它进入其他生物占据的空间也不会。如果其他生物接触到或进入旋涡，或者水元素移动进或穿越该生物占据的空间，那么该生物就会被卷入其中。

体型比水元素小一级或更多的生物被卷入旋涡时可能会受到伤害（详情见下表），也可能会被水流卷起。受影响的生物在接触旋涡时必须通过一个反射豁免检定，否则会将会受到表中列出的伤害。该生物也必须要通过第二次反射豁免检定，否则整个身体会被卷入其中并且被强劲的水流悬吊起来，每轮将会自动受到表中列出的伤害。受到影响的生物每轮都可进行一次反射豁免检定以逃离旋涡。生物仍会受到伤害但是如果豁免检定成功将会脱离旋涡。对抗旋涡的豁免检定DC因水元素体型而异（见下表）。该豁免检定DC基于力量调整值。

被卷入旋涡的生物除了被水元素带着移动或尝试逃脱之外不能移动。被卷入旋涡中的生物可以正常的做其他动作，但是必须在专注技能检定中获得成功（DC10 + 法术等级）才能施展法术。被卷入旋涡中的生物敏捷受到-4的罚值，在攻击检定上受到-2的罚值。水元素同时能困住的生物数量取决于其旋涡的体积。

水元素随时都能将其卷入的生物抛出来，它们会被丢到旋涡目前的位置。被召唤来的水元素在返回所属位面之前总会将被其困住得生物丢出来。

如果旋涡的基部接触到水底的话，将会产生一片旋转的沙砾云。这沙砾云以水元素为中心，直径等于旋涡高度的一半。沙砾云会遮挡5尺距离外的所有视觉能力，包括黑暗视觉。5尺之外的生物获得隐蔽，更远的生物则获得全隐蔽。被沙砾云笼罩的生物必须通过一个专注技能检定（DC15 + 法术等级）才能施展法术。

旋涡形态下的水元素不能进行挥击攻击，同时也不会威胁到其身边的区域。

s_water_vortex="Vortex" s_water_vortex_d=The elemental can transform itself into a whirlpool once every 10 minutes, provided it is underwater, and remain in that form for up to 1 round for every 2 HD it has. In vortex form, the elemental can move through the water or along the bottom at its swim speed. The vortex is 5 feet wide at the base, up to 30 feet wide at the top, and 10 feet or more tall, depending on the elemental’s size. The elemental controls the exact height, but it must be at least 10 feet.

The elemental’s movement while in vortex form does not provoke attacks of opportunity, even if the elemental enters the space another creature occupies. Another creature might be caught in the vortex if it touches or enters the vortex, or if the elemental moves into or through the creature’s space.

Creatures one or more size categories smaller than the elemental might take damage when caught in the vortex (see the table below for details) and may be swept up by it. An affected creature must succeed on a Reflex save when it comes into contact with the vortex or take the indicated damage. It must also succeed on a second Reflex save or be picked up bodily and held suspended in the powerful currents, automatically taking damage each round. An affected creature is allowed a Reflex save each round to escape the vortex. The creature still takes damage, but can leave if the save is successful. The DC for saves against the vortex’s effects varies with the elemental’s size. The save DC is Strength-based.

Creatures trapped in the vortex cannot move except to go where the elemental carries them or to escape the whirlwind. Creatures caught in the whirlwind can otherwise act normally, but must make a Concentration check (DC 10 + spell level) to cast a spell. Creatures caught in the whirlwind take a –4 penalty to Dexterity and a –2 penalty on attack rolls. The elemental can have only as many creatures trapped inside the vortex at one time as will fit inside the vortex’s volume.

The elemental can eject any carried creatures whenever it wishes, depositing them wherever the vortex happens to be. A summoned elemental always ejects trapped creatures before returning to its home plane.

If the vortex’s base touches the bottom, it creates a swirling cloud of debris. This cloud is centered on the elemental and has a diameter equal to half the vortex’s height. The cloud obscures all vision, including darkvision, beyond 5 feet. Creatures 5 feet away have concealment, while those farther away have total concealment. Those caught in the cloud must make a Concentration check (DC 15 + spell level) to cast a spell.

An elemental in vortex form cannot make slam attacks and does not threaten the area around it.

