-- 异怪		Aberration
s_naga			="纳迦"
s_naga_d		=[[所有纳迦都拥有细长的、被闪烁的鳞片所覆盖的蛇形身体，以及多少有些类似于人类的面孔。它们身长在10到20尺之间，体重在200到500磅之间。纳迦的眼睛明亮慧诘，燃烧着一种几乎可将人催眠的心灵之光。

纳迦偏爱法术胜于其他类型的战斗。因为它们总是在其守卫且熟知的巢穴中出现，所以它们可以按自己的意愿来安排大多数的遭遇。]]

-- 龙		Dragon
s_true_dragon	="真龙"
s_true_dragon_d	=[[真龙（而非其他属于龙类的生物）的已知种类可粗分为两个类别：五色龙及金属龙。

五色龙包括黑龙、蓝龙、绿龙、红龙及白龙，它们全都非常邪恶且极为凶狠。

金属龙则有黄铜龙、青铜龙、赤铜龙、金龙及银龙，它们都属于善良阵营，而且通常都很高贵，受到智者的高度尊崇。

所有龙都会随着年龄增长而获得更多的能力与更强的力量（其他属于龙类的生物并不会如此）。龙刚孵化时身长只有数英尺，而当它们成长到太古龙时可超过100英尺长。不同种类的龙体型准确的大小会根据年龄和种类有所不同。

所有龙都说龙语。]]
s_true_dragon_e	=[[一条龙的消化系统就像一个极高效的熔炉，甚至连无机物也能消化。有些龙还对无机物有特殊的口味。

虽然龙的目标及想法会因种类而有极大差异，但它们都十分贪婪。它们喜欢收藏财宝，收集成堆的钱币，并尽可能收集宝石、珠宝及魔法物品。那些拥有大批收藏品的龙不愿意离开这些宝藏太长时间，只有在巡视附近区域或找寻食物时才会离开巢穴。对于龙来说，财宝永远都不会足够。这些宝藏是如此赏心悦目，龙喜欢沉浸在宝藏的光辉之中。龙喜好用它们的宝藏作床铺，在上面弄出一个适合自己体型的隐蔽处。当龙成长到太古龙阶段时，它的皮肤上将会因此镶嵌上数百枚宝石。]]

s_half_dragon	="半龙"
s_half_dragon_d	=[[半龙生物总是比其没有龙类血脉的同族更加强壮，而且外观上也有很大差异 - 鳞片，瘦长的体形，爬虫类的眼睛，夸张的牙齿和爪子。有时候它们会长有翅膀。]]

-- 动物		Animal
s_rat			="鼠"
s_rat_d			=[[这些杂食性的啮齿动物几乎可以在任何地方繁衍。遭遇战斗时，它们通常会选择逃跑。啮咬仅作为它们的最后手段。]]

s_rat_x			="凶暴鼠"
s_rat_x_c		="这肮脏的老鼠体型几乎跟小狗一样大。它披着粗糙的皮毛，长尾巴光秃秃的，两只眼睛闪闪发光。"
s_rat_x_d		=[[凶暴鼠是杂食性的食腐动物，但是会为保卫巢穴和领土而展开攻击。成群的凶暴鼠在攻击时极为凶猛，用它们尖利的门牙啮咬并嚼碎对手。它们经常出没于地下城和城市下水道。

凶暴鼠能长到4尺长，体重超过50磅。凶暴鼠的体型几乎跟小狗一样大，披着粗糙的皮毛，长尾巴光秃秃的，两只眼睛闪闪发光。]]

s_cat			="猫"
s_cheetah		="猎豹"
s_leopard		="豹"
s_lion			="狮"
s_lion_x		="凶暴狮"
s_tiger			="虎"
s_tiger_x		="凶暴虎"

s_dog			="狗"
s_dog_ride		="骑乘用犬"
