s_wolf			="狼"
s_wolf_c		="这只强大的犬科动物有一双锐利的黄色眼珠，在它锋利的白牙之间伸出一条舌头。"
s_wolf_d		=[[狼是以固执和狡猾而著称的群居猎食者。狼单独或成群结队地行动，它们位于食物链顶端。它们具有凶猛的领土意识和异常广阔的狩猎范围，狼群散布在广大的区域中。

狼宽阔的脚爪上，脚趾之间含有轻巧的肉垫，能够让它们在雪地里移动，它们的皮毛很厚且防水，颜色从灰色到棕色，甚至有些种类是黑色。它们的爪子上包含嗅觉腺体，会在所有它们到过的地方留下记号，可以让狼群的其他成员知道它的下落。

一般来说，狼站立的时候肩高2.5至3尺，重量在45至150磅之间，雌性则略小。

它们最喜欢的战术是让几只单独的狼从正面攻击敌人，同时其他的狼绕个圈从敌人的后方进行夹击。]]

s_wolf_x		="凶暴狼"
s_wolf_x_c		="这只巨大的黑狼体型跟一匹马一样大，尖牙像匕首一样大和锋利。"
s_wolf_x_d		=[[凶暴狼是普通狼的巨大化版本，它代表了狼最原始的形态。这些生物的基本行为和普通的狼一样，但是更加具有攻击性。凶暴狼喜欢成群地攻击，尽可能包围和夹击对手。凶暴狼是群会杀死它们所能抓到的任何生物的高效猎人。

凶暴狼经常为巨人当做打猎的伙伴或凶猛的看门动物。一些凶残的人型生物和樵夫训练凶暴狼作为坐骑。

凶暴狼的毛色比一般的狼更深，趋向于黑色和斑驳的深灰色。成年凶暴狼一般大约9尺高，重量约800磅，体型跟马一样大，尖牙像匕首一样长和锋利。]]-- 凶暴狼的皮毛是斑驳的灰色与黑色，约9尺长，重约800磅。

