s_dire_animal	="凶暴动物"
s_dire_animal_d	=[[凶暴动物是一般动物的更大、更难缠、更好斗的版本。它们通常具有凶残的、史前的、甚至恶魔般的外貌。]]

s_dinosaur		="恐龙"
s_dinosaur_d	=[[恐龙的状貌体型各异。较大的恐龙通常呈土褐色，而较小的肤色更具变化性。多数恐龙皮肤都纹理粗糙。

恐龙在战斗中会充分发挥速度和体型的优势。这些行动迅捷的食肉动物会跟踪猎物，隐藏自己的身形直到接近目标后发动冲锋攻击。草食性恐龙通常会冲撞并跺踏目标。]]

-- 魔法兽	Magical Beast
s_basilisk		="石化蜥蜴"
s_basilisk_c	="这只矮胖的爬虫类怪物有八条腿，背后突出许多骨刺，眼睛放射出灼热的浅绿色光芒。"
s_basilisk_d	=[[石化蜥蜴是一种爬行类怪物，活着的生物只要被它凝视一眼就会变成石头。

石化蜥蜴通常有着暗棕色的身体和黄色的下腹部。某些品种的鼻子上还会长出一根短而弯的角。成年石化蜥蜴可以长到6英尺长，如果算上尾巴的话还可以再加上5到7尺的长度。这种生物重约300磅。

石化蜥蜴依赖于它的凝视攻击，只有当对手足够近的时候才会用啮咬攻击。尽管它有八条腿，但是由于新陈代谢缓慢，所以它们不会把力气花在不必要的地方。入侵者撞见石化蜥蜴时，若选择逃跑而非战斗，会发现对方在追击时有点漫不经心。

石化蜥蜴大部分时间都是在躺着等待猎物，包括小型哺乳动物，鸟类，爬虫类以及类似的生物。]]
s_basilisk_e	=[[石化蜥蜴，经常被称为“蛇王”，实际上它完全不是蛇类，而是拥有八条腿的爬虫类。它有着恶劣的性格，善于用凝视把生物变成石头。民间传说记载，类似于鸡蛇兽，第一只石化蜥蜴是蛇下的蛋由公鸡孵化所生。但是石化蜥蜴所表现出的生物特征却难以让人相信这一点。

石化蜥蜴生存与任何地面环境，从森林到沙漠，并且它们喜欢隐藏于和自己相协调的环境中——一只沙漠中居住的石化蜥蜴会是棕褐色的，而居住于森林中的石化蜥蜴则会是浅绿色。它们喜欢在岩穴、挖出的洞穴或其他可以获得庇护的居所，而且它们的巢穴里会装饰着人和动物的雕像——还保持着生前的姿势和不幸撞见石化蜥蜴时脸上错愕惊恐的表情。

石化蜥蜴能够以他们石化的生物为食，他们剧烈翻滚着的酸性胃液能从石头中吸取养分，但是过程十分缓慢，这让它们十分懒散和行动迟缓。所以，石化蜥蜴会偷偷接近以捕食那些躲过他们凝视的猎物，依靠它们的潜行和出其不意的袭击来保证它们自己的安全和胃口都能得到满足。它们平时以捕食小动物、小鸟和爬虫类为食，当它们不捕食的时候，会在巢穴里睡觉以打发时间。而那些足够勇敢到想去捕获石化蜥蜴或者从它们身边偷取财宝的冒险者们会发现它们其实简直天生的卫兵和守财奴。

一只成年的石化蜥蜴有13尺长，它们的长尾巴就占了一半长度，重量则达300磅。有些品种则在鼻子上长出弯曲的尖角，或者在头顶长出骨质的角冠，就好像皇冠一般。它们一般是独居生物，但是在交配和生蛋时会聚集在一起，在特别危险的区域里它们会成群聚集以保护自己并攻击来犯之敌。

由于某些不明原因，黄鼠狼和雪貂对石化蜥蜴的凝视免疫，会在石化蜥蜴的父母出去狩猎时潜入它们的巢穴中，吃光它们的幼崽。另外有传言表示石化蜥蜴的血液能把普通石料变成别的材质，但是这有可能是目击者看到了石化蜥蜴血液复原被石化的生物或肢体的事实，从而产生的误解。]]

s_liz_l	="电蜥蜴"
s_liz_l_c	="这只狗一样大的蜥蜴长着两只犄角，头两侧一边一只。身体的鳞片上闪烁着蓝色的电火花。"-- 绿色的鳞片...
s_liz_l_d	=[[电蜥蜴身体下方呈浅灰色或蓝色，至其背部逐渐变暗。它的背部和尾部上有蓝黑色的斑纹。

电蜥蜴肩高约1尺，重约25磅，体型跟狗一样大，长着两只犄角，头两侧一边一只，身体的鳞片上闪烁着蓝色的电火花。

电蜥蜴依赖其电击能力进行战斗。电蜥蜴只有在其电击使其对手昏迷或者完全无效时才会啮咬对手。单独一只电蜥蜴会在放出电击之后逃走，但如果周围有其他电蜥蜴的话，它们会伙同同伴一起给予敌人致命的电击。]]
s_liz_l_e	=[[电蜥蜴的腹部是淡黄色的，亮绿色的鳞片复盖着它3尺长的身体，重量约为25磅。电蜥蜴倾向于群居，当它们彼此接近时，它们的放电能力会随之增强。

电蜥蜴的群落通常靠近水源。一旦群落在一个地点定居，这些蜥蜴就变得非常具有领土性并且会攻击任何入侵者。单独的电蜥蜴是胆小而怯懦的生物——但是当数只电蜥蜴聚集的时候它们会变成强大和可怕的对手，能够杀死几倍于自己体形的生物。

电蜥蜴在战斗中依靠其放电能力进行战斗，并且喜欢在用电击让人失去意识之后，或当它们的电击看起来毫无影响时才进行噬咬攻击。一个单独的电蜥蜴会在放电之后逃离战场，但是如果附近有多只电蜥蜴的话，它们会齐心协力向敌人射出致命的闪电。

许多人试图捕捉和驯服电蜥蜴，但是这通常都是痛苦而困难的任务。单独囚禁的电蜥蜴会迅速衰弱而死，除非它们花费大量的时间来和同伴们一起玩耍嬉闹。如果驯养成对或更多数量的电蜥蜴，它们会茁壮成长，但是它们群聚在一起时的放电能力让那些不能免疫电击的驯养者更为头疼。]]

-- 虫类		Vermin
s_ant_g		="巨蚁"
s_ant_g_c	="一只有着六条细长腿的蚂蚁有一匹站着的矮种马一般大小，它的上颚不断开合，它的刺上不断滴落毒液。"
s_ant_g_d	=[[巨蚁是所有虫类生物中最坚韧，也是适应性最强的一种。

巨蚁的体型跟矮种马差不多。巨兵蚁和巨工蚁约6尺长，巨蚁后则可长至9尺。

巨蚁跟普通体型的他们的亲戚一样勤劳。虽然他们的巢里不是由上千蚂蚁组成，但是他们获得的体型上的好处远远弥补了这一点。]]

s_spider_mons	="变种蜘蛛"
s_spider_mons_c	="一只像人那么大的蜘蛛静悄悄地从它漏斗型的网深处爬出。"
s_spider_mons_d	=[[所有的变种蜘蛛都是攻击性极强的掠食者，它们使用其剧毒的啮咬来克制或杀死猎物。

变种蜘蛛可分为两个类别：狩猎蛛和结网蛛。狩猎蛛到处跑来跑去，结网蛛则通常尝试用蛛网捕捉猎物。狩猎蛛能结网来做为巢穴，但不能像结网蛛一样使用蛛网作为武器。]]-- 狩猎蛛的基本陆地速度比数据表中所列出的要快10尺。	A hunting spider has a base land speed 10 feet faster than the figures given in the statistics blocks.

-- 植物		Plant

-- 泥形怪物	Ooze

-- 不死生物	Undead
s_skeleton		="骷髅"
s_skeleton_d	=[[骷髅是会活动的骨骸，遵循其邪恶主宰的命令而行动的没有心智的傀儡。

除了在被杀之际所穿盔甲的腐烂碎块外，这些不死生物很少带着其他东西。

骷髅只执行它们接受的命令，它们没有自主的推断力。由于这个限制，给予他们的命令通常很简单。

骷髅会一直战斗直到被摧毁。]]

s_zombie	="僵尸"
s_zombie_d	=[[僵尸是被黑暗而罪恶的法术所复活的尸体。

由于它们极度缺乏智力，所以对刚创造出来的僵尸下达命令时必须非常简单扼要。]]

s_ghost		="幽魂"
s_ghost_d	=[[幽魂是智慧生物所遗留下来的灵体，它们因为某些理由无法轻易安息在墓穴里。

幽魂的外貌与生前大致相同，但有些情况下其灵体外貌会有一些改变。]]

s_ghoul		="食尸鬼"
s_ghoul_c	="这个人型生物长着长而锋锐的牙齿，它死白的皮肉紧绷绷地撑在因饥饿而拉伸的骨头架子上。"
s_ghoul_d	=[[食尸鬼是一种在墓园中活动，依靠吞噬尸体维持存在的不死生物。在传说中，第一个食尸鬼乃是世界上头一个嗜食人肉的人类所化，在他死时，这个恶人对活物血肉无止境的渴求将它带回阳世；另一种说法是某个以自己亲族的腐肉维生者，在他死于一种秽恶的疾病（并以食尸鬼的状态复生）后成为了第一个食尸鬼——总而言之，对于这些不死的拾荒者迄今为止还缺乏一个确定的起源说。

食尸鬼在文明世界的边缘地带潜伏着（比如城市周边的公墓和下水道中），在这些地方它们能轻松的获取自己需要的食物。虽然食尸鬼更爱腐肉的味道（并经常将它们的受害者埋上一段时间调调味），不过在饥饿的状态下它们也同样很难抗拒杀戮和进食活物的冲动。多数生活在地表的食尸鬼处于原始的状态，不过也有谣传提到在深深的地下，一些食尸鬼的牧师统治着整个由食尸鬼组成的王国，它们供奉远古的邪神和同样饥渴的恶魔领主作为保护者。当然，更加“文明”的食尸鬼并不会考虑太多餐桌礼仪问题。事实上，想想由整个族群的食尸鬼围坐一桌共飨人肉大宴和公墓里的食尸鬼在棺材堆里翻箱倒柜，哪一个画面要更加骇人一些？]]
--[[
疾病（Su）：食尸鬼热疫：啮咬——伤口传播；豁免：强韧豁免DC13；潜伏期：1天；发作频率；1天；效果：1d3体质和1d3敏捷伤害；治愈：2次连续检定通过。这个疾病的豁免DC基于魅力。死于食尸鬼热疫的类人生物将在下一个午夜被转化为食尸鬼，新生的食尸鬼将失去所有生前的能力。该食尸鬼不受其他食尸鬼的控制，但是其行为和思想将被完全转换为对活物血肉的渴求——和所有的食尸鬼一样。高于4HD的类人生物将被转化为妖鬼。
妖鬼 Ghast	妖鬼是拥有进化模版的食尸鬼，这些怪物的麻痹能力对精灵同样有效。妖鬼通常和自己的同类集群活动，或者是领导一群低级的食尸鬼。妖鬼会散发出一种强到令人窒息的腐败恶臭，这种特殊能力足以影响活物（范围10尺，坚韧豁免DC15无效，效果：恶心1d6+4轮）
水鬼 Lacedon	水鬼是拥有水栖亚种的食尸鬼近亲，它们时候在诸如暗礁这类经常会有船只失事的地区。水鬼具有30尺的基础速度和30尺的游泳速度。
Disease (Su) Ghoul Fever: Bite—injury; save Fort DC 13; onset 1 day; frequency 1/day; effect 1d3 Con and 1d3 Dex damage; cure 2 consecutive saves. The save DC is Charisma-based. A humanoid who dies of ghoul fever rises as a ghoul at the next midnight. A humanoid who becomes a ghoul in this way retains none of the abilities it possessed in life. It is not under the control of any other ghouls, but it hungers for the flesh of the living and behaves like a normal ghoul in all respects. A humanoid of 4 Hit Dice or more rises as a ghast.
Ghast	Ghasts are ghouls with the advanced monster template. A ghast's paralysis even affects elves. Ghasts roam in packs of their own kind or lead groups of common ghouls. The stink of death and corruption surrounding these creatures is overwhelming, granting them the stench extraordinary ability (10-foot radius, Fort DC 15 negates, sickened for 1d6+4 minutes).
Lacedon	These aquatic cousins of the ghoul lurk near hidden reefs or other places where ships are likely to meet their ends. Lacedons have a base land speed of 30 feet and a swim speed of 30 feet.
]]
s_lich		="巫妖"
s_lich_d	=[[巫妖是会施法的不死生物，通常是利用其法力以非自然的方式来延长其生命的法师或术士，有时也会是牧师或其他施法者。

巫妖是枯瘦且骷髅般的类人生物，它们凋萎的肌肉紧附在裸露的骨头上。它们的眼睛很早以前就因腐朽而消失，但是在其空洞的眼眶中仍然闪烁着针尖般的绯红光芒。

巫妖会说通用语及它生前所会的任何语言。

<b>巫妖人物</b>
变成巫妖的过程是无法形容的邪恶，并且只有自愿的人物才能承受。巫妖保留其生前所有职业能力。

<b>巫妖的命匣</b>
变成巫妖必不可少的部分就是制造一个用来储存生命能源的魔法命匣。每个巫妖都必须要制造它自己的命匣。

最常见的命匣外形是一个被封印的装有撰刻着魔法文字的羊皮纸的超小型金属盒。其他外形的命匣也存在，比如戒指，护符或类似的物品。

按照规则，消灭巫妖的唯一方式就是摧毁其命匣。除非其命匣被定位且被摧毁，巫妖会在它看上去被杀死后的1d10天内重生。]]

s_vampire	="吸血鬼"
s_vampire_d	=[[吸血鬼的外表如生前一般，只是容貌变得冷酷而野蛮，使它们看起来有狼一般的掠食者特征。

和巫妖类似，他们爱慕虚荣而又颓废，并可能以贵族自居。

虽然有着人类的特征，吸血鬼仍然很容易辨认，它们不会投下影子，也不会在镜子中留下映像。

吸血鬼会说他们生前所会的语言。]]
s_vampire_e	=[[<b>吸血鬼的弱点</b>
尽管威力非凡，吸血鬼也有相当多的弱点。

<b>驱除吸血鬼：</b>吸血鬼无法忍受强烈的大蒜气味，所以不会接近有那种玩意儿的地方。类似的，会因镜子或强大的神圣徽记而畏缩。这些东西不会伤害吸血鬼 — 他们只是不想靠近。一个畏缩的吸血鬼必须至少与拿着镜子或圣徽的生物保持５尺距离并在该遭遇的剩余时间中都不能接触或近身攻击拿者那类物品的生物。

吸血鬼也不能穿过流水，但是它可以乘船渡过或在棺材里休息时被抬过去。

除非被主人邀请，否则他们也不能进入其他人的家或房子。他们可以进入那些明确说明对所有人开放的公共场所。

<b>杀死吸血鬼：</b>将吸血鬼的生命值降到０或更低可以使之无力化却不能杀死它。但是，有些攻击可以杀死吸血鬼。

被暴露在阳光下会使得吸血鬼迷乱：它将只能做一个移动动作或攻击动作然后如果它无法逃脱，则在下一轮被完全摧毁。

类似的，将吸血鬼没入流动的水中将每回合让其损失１／３的生命值，直到第３回合它将被彻底摧毁。

将木桩插进吸血鬼的心脏也会瞬间杀死这个怪物。但除非身体被毁灭，它仍将在木桩被拔除时复活。

一个流行的方法是砍下它的脑袋然后将其嘴里灌满圣水（或其他类似的东西）。]]

s_vampire_spawn		="吸血衍体"
s_vampire_spawn_d	=[[吸血衍体是吸血鬼杀害凡人时产生的不死生物。如同它们的制造者一般，衍体也受缚于它们的棺材以及墓土。吸血衍体和生前看起来差不多，只是线条变得冷酷而显得凶恶。

当遭遇凡人时，吸血衍体会使用它们非人的力量拳夯对手并拿对手往墙上或石头上撞。它们也使用气态形体和飞行能力寻找对手的弱点攻击。

吸血衍体对所有可以驱除或杀死吸血鬼效果的攻击同样显得十分脆弱。

吸血衍体说通用语。]]

-- 构装体	Construct
s_golem		="魔像"
s_golem_d	=[[魔像是由魔法力量构建而成的自动装置。创造魔像的过程通常要涉及到强大的魔法和元素力量的运用。

魔像的活化力量源于来自土元素位面的灵魂。创造魔像，简而言之就是将一个不情愿的灵魂植入到人造躯体内，并让其按照创造者的意志行动。

魔像在战斗中相当顽强，而它们的身体也异乎寻常的强壮，而且对大多数魔法和超自然能力免疫。由于没有心智，如果没有创造者的指令他们什么也不会干。它们会明确的执行命令，但不懂得采取任何战略或战术。战斗中它们毫无感情，挑衅对于他们是无效的。]]
s_golem_e	=[[只要魔像在创造者周围60尺范围内，能够看见他并听到他的声音，创造者就可以对它下达指令。如果未接到新的指令，魔像会尽力完成所接到的最后一项指令，但如果它遭到攻击，仍会反击。

当创造者不在的时候，他或她可以事先向魔像下达一些简单的指令来控制它的行动。创造者可以命令魔像听从其他人发出的指令（此人也可以将魔像的控制权交给他人，依次类推），无论如何创造者可以随时重新控制他的造物，让它只听其一人的命令。]]

s_inevitable	="制裁者"
s_inevitable_d	=[[制裁者是将执行多元宇宙中的自然法规作为其唯一存在目的的构装生物。

每种制裁者都被设计成能寻找并惩罚某种特定的罪行，捉拿违犯了基本法规的个人或团队。当一个制裁者被制造出来时，它会接到它的第一次任务，然后去找到犯法者并给予其适当的惩罚。判决通常为死刑，但一些制裁者会坚决要求犯罪的团队进行补偿，并使用指使术或审判烙印或来确保其服从。

制裁者处于监视模式时在人群中格外醒目，但它们看起来对此毫不在意。它们形态各异，但所有的制裁者都是金银制的发条生物，齿轮和活塞就是它们的肌肉。它们的眼睛闪烁着金色的光芒。

与绝大多数的构装生物不同，制裁者拥有智力属性值，并且可以思考、学习和记忆。

制裁者说深渊语，天界语，炼狱语和它们首个目标的母语。]]
s_inevitable_e	=[[从它起步开始，制裁者会完全专注于它的目标。无论线索多么模糊，任务多么无望，它都会坚持不懈。制裁者一心一意地追击它们的猎物，它们奉命不干涉无辜者。它们猎物的同伙是可以攻击的对象，然而，有些时候这会在它们的程序中产生矛盾。

除非威胁到其自身安全，制裁者会完完全全地专注于其目标，完全忽视其他战斗人员的存在。制裁者可能会攻击任何阻碍它的人，但它若能再次着手于其目标的话则不会多做停留。制裁者十分重视自我保护；任何人若对制裁者展开它所认为能致命的攻击的话，也会受到同样致命的反击。

制裁者很乐意牺牲自己以完成任务，但是它们不会自杀。面对失败时，它们会撤退并寻找机会反击。它们是坚决而耐心的对手。如果有助于完成任务它们会与其他人联盟，但这联盟不会维持很久。]]

-- 其他		Others
s_lycanthrope	="兽化人"
s_lycanthrope_d	=[[兽化人是能够变化成动物的类人生物或巨人类生物。

在其天生形态下，兽化人看起来就和它的同类生物一样，但是天生兽化人和那些被传染了很久的兽化人会拥有其动物形态的特征。

在动物形态下，兽化人像是更加强悍的普通动物，但如果靠近观察的话，可以看到它的眼睛（在黑暗中会发红光）中闪耀着不寻常的智慧的火花。

兽化症可以像疾病一样传播。有时普通的类人生物或巨人类生物在被兽化人攻击而受伤之后会感染兽化症。这样的生物被称为受传染的兽化人。其他生下来就是兽化人的兽化人，被称为天生兽化人。

常见的兽化人包括狼人，鼠人，熊人，虎人和野猪人等。]]
s_lycanthrope_e	=[[处于类人（或巨人）形态下的兽化人会使用其同类生物所使用的任何战术和武器，然而会更具攻击性。兽化人拥有其动物形态的官能，包括灵敏嗅觉和昏暗视觉，而且还可以深刻地理解它所能变化成的那类动物（并拥有与之交流的能力）。受传染的兽化人如果在战斗中受伤就可能被愤怒所压倒，使其非自发地变成动物形态。

动物形态下的兽化人就如其所变成的动物一样战斗，但它的啮咬攻击却可传播兽化症。它非常狡诈而且极为强壮，并且拥有只能被镀银武器所击破的伤害减免能力。

天生兽化人（或意识到自己已被传染的受传染兽化人）可以变成混合了其类人和动物形态的混种形态。混种形态下的兽化人有手且可使用武器，但也可以使用其利齿和爪子进行攻击。混种形态下的兽化人可以通过其啮咬攻击传播兽化症，而且拥有与其动物形态相同的伤害减免能力。]]


s_u_tps			= "生物类型"
s_u_tps_d		= [[每种生物都从属某一物种（类型），其大致决定了生物的能力。某些生物还会从属于一个或多个亚种（子类型）。

除非受到特殊能力的影响，否则生物无法违背其物种的特性 — 而新的生物模板可能会彻底改变生物原有种族特性。


每种生物类型的描述都以相同的格式组织，如下所述。


<b>生命骰（简称HD）</b>
有两种含义，一是决定生物生命值的骰面。虽然还有体质值等因素，但生命骰可作为一项重要参考来衡量生物的生命值。

另一含义是衡量生物强度的数值，类似于玩家角色等级，但无职业（或某些复杂情况）的生物需用生命骰数来代替此强度数值。


<b>基本攻击加值（简称BAB）</b>
基于生物类型，生物的BAB等于其HD总数（类似于战士），或3/4（类似于牧师），或1/2（类似于法师）。


<b>强项豁免</b>
不同的生物类型有不同的强项豁免：某项或多项豁免高于其他豁免。不过也有少数生物类型各项豁免都很强。


<b>每HD技能点数</b>
生物每获得一个HD，获得的技能点数为x + 智力调整值，最少为1。首个HD的技能点数为此点数的4倍。

但前提是此生物有智力值，否则它的每HD技能点数为0。有些生物类型没有心智，也无法获得技能点数和专长。


<c=twa>（完整起见，以下给出规则中所有的生物类型以供参考，包括那些尚未出现在游戏中的。）</c>]]-- <c=o>房规：目前游戏中所有生物的BAB均为其HD总数（或等级）的1/2，因此此项仅供参考。</c><c=o>House Rule: All creatures in game currently have a BAB equal to 1/2 of their total HD (or level), so this entriy is for reference only.</c><c=o>Règle de la maison : toutes les créatures du jeu ont actuellement un BAB égal à la moitié de leur DV total (ou niveau), donc cette entrée est pour référence seulement.</c>


s_u_sub_tps		= "生物亚种"
s_u_sub_tps_d	= [[有些生物有一个或多个亚种。亚种能为生物增加额外的能力和特性。

<c=twa>（完整起见，以下给出规则中所有的生物亚种以供参考，包括那些尚未出现在游戏中的。）</c>]]


s_ut_hum_hd		= "类人生物的生命骰"
s_ut_hum_hd_d	= [[只有一个生命骰的类人生物，用PC或NPC职业的职业特性来代替他的类人生物生命骰中的特性。

此类类人生物体现为1级武者，表明他们具备一般的战斗能力和较弱的豁免。

只有具有不止一个生命骰的类人生物才使用类人生物的特征。]]


u_tps_text={-- z_u_tp

[uc_hum]={n="类人生物"	,d=[[类人生物通常具有双臂、双腿及一个脑袋，或者有类似于人类的躯干、四肢和头部。

类人生物只有很少的超自然能力或特异能力，或者完全没有，但他们大多数可以用语言交谈，并通常有较为发达的社会结构。

他们的体型通常为中或小体型。每个类人生物都属于一个亚种。

<b>特征：</b>
- 生命骰：d8；或由职业等级决定。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：反射（通常为反射，但不同的类人生物具有不同的强项豁免）。
- 每HD技能点数：2 + 智力调整值；或由职业等级决定。

<b>特性：</b>
- 擅长所有简易武器；或由职业等级决定。
- 如穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌；或由职业等级决定。
- 需要进食、睡眠和呼吸。]]},


[uc_gnt]={n="巨人"	,d=[[巨人是类人形状的生物，力量巨大，通常至少是大体型。

所有巨人都会说巨人语。智力值10或以上的巨人还会说通用语。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：强韧。
- 每HD技能点数：2 + 智力调整值。

<b>特性：</b>
- 昏暗视觉。
- 擅长所有简易和军用武器，以及任何天生武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。
- 需要进食、睡眠和呼吸。]]},


[uc_fey]={n="精类"	,d=[[精类是具有超自然能力的生物，他们和自然界或一些其他的力量或地点联系在一起。精类通常具有人类的外形。

<b>特征：</b>
- 生命骰：d6。
- 基本攻击加值：1/2 HD总数。
- 强项豁免：反射和意志。
- 每HD技能点数：6 + 智力调整值。

<b>特性：</b>
- 昏暗视觉。
- 擅长所有简易武器和所使用武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。
- 需要进食、睡眠和呼吸。]]},


[uc_hmm]={n="人形怪物"	,d=[[人形怪物与类人生物相似，但同时具有怪物或动物的特征。他们通常也具有魔法能力。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：HD总数。
- 强项豁免：反射和意志。
- 每HD技能点数：2 + 智力调整值。

<b>特性：</b>
- 黑暗视觉60尺。
- 擅长所有简易武器和所使用武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。
- 需要进食、睡眠和呼吸。]]},


[uc_out]={n="异界生物"	,d=[[异界生物至少有一部分本质（但不一定是物质）是主物质位面以外的某个位面的产物。

一些生物可能原本属于其它类型，当它们达到更高（或更低）层次的精神状态时变成了异界生物。

典型的异界生物包括天使，魔鬼和巨灵等。而神魔裔则是较典型的本地异界生物。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：HD总数。
- 强项豁免：强韧、反射和意志。
- 每HD技能点数：8 + 智力调整值。

<b>特性：</b>
- 黑暗视觉60尺。
- 与大多数活物不同，异界生物不具二元性 - 它的灵魂和身体合二为一。当一个异界生物死亡时，不会有灵魂得到释放。将灵魂返还身体的普通法术对非本地异界生物无效。它需要更强力的法术效果来让它恢复生命。
- 擅长所有简易和军用武器，以及所使用武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。
- 需要呼吸，但不需要进食或睡眠（虽然如果想要的话它们也可以这么做）。本地异界生物需要进食、睡眠和呼吸。]]},


[uc_elm]={n="元素"	,d=[[元素是由四种基本元素：风、土、火、水之一所形成的生物。元素生物就是形成万物的元素的化身。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：强韧（土、水）或反射（风、火）。
- 每HD技能点数：2 + 智力调整值。

<b>特性：</b>
- 黑暗视觉60尺。
- 对毒素、魔法睡眠、麻痹和震慑免疫。
- 不受重击或夹击。
- 与大多数活物不同，元素不具二元性 - 它的灵魂和身体合二为一。当一个元素死亡时，不会有灵魂得到释放。将灵魂返还身体的普通法术对它无效。它需要更强力的法术效果来让它恢复生命。
- 仅擅长它的天生武器。除非通常处于类人形态，则擅长所有简易武器和所使用武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。
- 不需要进食、睡眠或呼吸。]]},


[uc_abr]={n="异怪"	,d=[[异怪通常具有奇异的生理结构，千奇百怪的特殊能力，怪异的思维方式，或者这三者的任意组合。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：意志。
- 每HD技能点数：2 + 智力调整值。

<b>特性：</b>
- 黑暗视觉60尺。
- 擅长它的天生武器。若通常形态类人，则擅长所有简易武器和所使用武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。
- 需要进食、睡眠和呼吸。]]},


[uc_dgn]={n="龙"	,d=[[龙是一种类爬虫生物，他们通常有翅膀、具有魔法和非凡的能力。

<b>特征：</b>
- 生命骰：d12。
- 基本攻击加值：HD总数。
- 强项豁免：强韧、反射和意志。
- 每HD技能点数：6 + 智力调整值。

<b>特性：</b>
- 黑暗视觉60尺和昏暗视觉。
- 免疫魔法睡眠和麻痹。
- 仅擅长它的天生武器。若正处于或可变成类人形态，则擅长所有简易武器和所使用武器。
- 不擅长任何盔甲。
- 需要进食、睡眠和呼吸。]]},


[uc_ani]={n="动物"	,d=[[动物是非人类的活体生物，通常为不具有魔法属性也不具有语言和文化天赋的脊椎动物。

这些生物通常依其本能而行动，由食物、繁殖之类的最基本需求所驱动。除非本身或其幼崽受到威胁，大多数的动物，即使是食肉动物，也不会主动攻击。

尽管通过驯养动物技能可以驯服动物或教会它做一些把戏，但是动物没有进行详细推理的能力。

一些食草动物通常不会使用其天生武器进行攻击。同样的，它们的天生武器被视为次要攻击。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：强韧和反射（凶暴动物3项豁免均为强项；个别动物有不同的强项）。
- 每HD技能点数：2 + 智力调整值。

<b>特性：</b>
- 智力值为1或2（不存在智力值高于2的动物）。
- 昏暗视觉。
- 阵营：总是中立。动物不受人类道德的支配。
- 宝藏：通常不拥有宝藏，若有也是被其杀死的生物所留下的。
- 仅擅长它的天生武器。非战斗草食动物使用其天生武器视为次要攻击。这样的攻击在攻击判定上有-5减值，并且在伤害调整值上只能获得1/2它的力量调整值。
- 除非经过战斗训练，否则无法擅长任何盔甲。
- 需要进食、睡眠和呼吸。]]},-- 宝藏：无。动物不会拥有宝物。	Treasure: None. Animals never possess treasure.


[uc_anm]={n="魔法兽"	,d=[[魔法兽和动物相似，但是可以具有高于2的智力值。魔法兽通常具有超自然或特异能力，但有时候仅仅是在外表或习性上奇特而已。

<b>特征：</b>
- 生命骰：d10。
- 基本攻击加值：HD总数。
- 强项豁免：强韧和反射。
- 每HD技能点数：2 + 智力调整值。

<b>特性：</b>
- 黑暗视觉60尺和昏暗视觉。
- 仅擅长它的天生武器。
- 不擅长任何盔甲。
- 需要进食、睡眠和呼吸。]]},


[uc_bug]={n="虫类"	,d=[[虫类包括昆虫、蜘蛛、其他节肢动物、蠕虫以及类似无脊椎动物。

此类生物依本能行动，由食物及繁殖之类的基本需求所驱动。虫类生物通常只有在饥饿或受到威胁时才会攻击。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：强韧。
- 每HD技能点数：2 + 智力调整值。大多数虫类没有心智，也无法获得技能点数和专长。

<b>特性：</b>
- 无心智：没有智力值，免疫所有影响心灵的效果。
- 黑暗视觉60尺。
- 阵营：总是中立。虫类不受人类道德的支配。
- 宝藏：通常不拥有宝藏，若有也是被其杀死的生物所留下的。
- 仅擅长它的天生武器。
- 不擅长任何盔甲。
- 需要进食、睡眠和呼吸。]]},


[uc_plt]={n="植物"	,d=[[这一类型由植物类的生物组成。注意，通常的植物，比如在田野或者果园中种植的植物，缺少感知和魅力属性，不是生物而是物体，即使它们是活着的。

<b>特征：</b>
- 生命骰：d8。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：强韧。
- 每HD技能点数：2 + 智力调整值。某些植物没有心智，也无法获得技能点数和专长。

<b>特性：</b>
- 昏暗视觉。
- 免疫所有影响心灵的效果。
- 免疫毒素、睡眠、麻痹、变形和震慑。
- 不受重击。
- 仅擅长它的天生武器。
- 不擅长任何盔甲。
- 需要进食和呼吸，但不需要睡眠。]]},


[uc_ooz]={n="泥形怪物"	,d=[[泥形怪物是无具体形状或易变形的生物，通常没有心智，活着就是为了吃。

它们栖息于各地的地下区域，侵蚀而成的洞穴，废墟和地下城中，寻找有机物 — 无论死活。

泥形怪物会攻击它们遇到的任何生物。它们会用伪足猛击或干脆用身体吞噬对手，身体分泌的酸液能帮助它们捕捉或消化猎物。

<b>特征：</b>
- 生命骰：d10。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：无。
- 每HD技能点数：2 + 智力调整值。大多数泥形怪物没有心智，也无法获得技能点数和专长。

<b>特性：</b>
- 无心智：没有智力值，免疫所有影响心灵的效果。
- 目盲（但具有盲视特性），免疫凝视攻击、视觉效果、幻象和其他依赖视觉的攻击形式。
- 盲视（特异）：泥形怪全身都遍布感觉器官，它们会自动察觉周围60尺内的气味和振动。
- 免疫毒素、睡眠、麻痹、变形和震慑。
- 不受重击或夹击。
- 某些泥形怪物能够对物体造成强酸伤害，每接触一整轮造成的伤害 = 10 + 1/2泥形怪物的HD + 它的体质调整值。
- 仅擅长它的天生武器。
- 不擅长任何盔甲。
- 需要进食和呼吸，但不需要睡眠。]]},


[uc_und]={n="不死生物"	,d=[[它们曾经是生物，但在死去以后被精神或超自然力量活化了，成为了不死生物。

<b>特征：</b>
- 生命骰：d12。
- 基本攻击加值：1/2 HD总数。
- 强项豁免：意志。
- 每HD技能点数：4 + 智力调整值。很多不死生物没有心智，也无法获得技能点数和专长。

<b>特性：</b>
- 无体质值。
- 黑暗视觉60尺。
- 免疫所有影响心灵的效果。
- 免疫毒素、睡眠、麻痹、震慑、疾病和死亡效果。
- 免疫任何需要强韧豁免的效果（除非此效果同样对物体有效，或无害）。
- 不受重击、非致命伤害、属性吸取、能量吸取的影响。免疫对身体属性（力量、敏捷、体质）造成的伤害，免疫疲劳和力竭的效果。
- 若无智力值则无法自己医治伤害，但可以被治疗。负能量可以治疗不死生物。快速痊愈特性不管是否有智力值都一样运作。
- 不受死者复生等法术或类法术能力影响。
- 专注检定时使用魅力调整值。
- 擅长它的天生武器，所有简易武器和所使用武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。
- 不需要进食、睡眠或呼吸。]]},-- 不会因巨创而死亡。在生命值减为0或更低的时候便立即被摧毁。	复活术和完全复活术能影响不死生物。它们会将不死生物变回它们在变为不死生物之前的活物。	Not at risk of death from massive damage, but when reduced to 0 hit points or less, it is immediately destroyed.		Resurrection and true resurrection can affect undead. These spells turn undead creatures back into the living creatures they were before becoming undead.


[uc_cst]={n="构装体"	,d=[[构装体是活化的物体，或人工制造的生物。

<b>特征：</b>
- 生命骰：d10。
- 基本攻击加值：3/4 HD总数。
- 强项豁免：无。
- 每HD技能点数：2 + 智力调整值。大多数构装体没有心智，也无法获得技能点数和专长。

<b>特性：</b>
- 无体质值。
- 黑暗视觉60尺和昏暗视觉。
- 免疫所有影响心灵的效果。
- 免疫毒素、睡眠、麻痹、震慑、疾病、死亡和死灵系效果。
- 免疫任何需要强韧豁免的效果（除非此效果同样对物体有效，或无害）。
- 不受重击、非致命伤害、属性伤害、属性吸取、疲劳、力竭和能量吸取影响。
- 无法自行回复伤害，但常常可以在某些特定效果下得到修复。具有快速痊愈特性的构装体仍可同样的自疗。
- 因为它不是活物，所以无法被复生或复活。
- 因为它的身体是一块无生命的物质，构装体很难被摧毁。根据体型它获得额外生命值，如下表：
	构装体大小	生命值奖励
	超微型		-
	微型		-
	超小型		-
	小型		10
	中型		20
	大型		30
	超大型		40
	巨型		60
	超巨型		80
- 仅擅长它的天生武器。若通常形态类人，则擅长所使用武器。
- 不擅长任何盔甲。
- 不需要进食、睡眠或呼吸。]]},-- ，或通过使用制造构装体专长修复	不会因巨创而死亡。在生命值减为0或更低的时候便被摧毁。	or through the use of the Craft Construct feat	— Not at risk of death from massive damage. Immediately destroyed when reduced to 0 hit points or less.
}

-- z_u_sub_tp
u_sub_tps_text={
[ust_hum]={n="人类"			,d="此亚种包括人类，或和人类有血缘关系的生物。"},
[ust_elf]={n="精灵"			,d="此亚种包括精灵，或和精灵有血缘关系的生物，如半精灵。\n\n精灵亚种生物有昏暗视觉。"},
[ust_dwf]={n="矮人"			,d="此亚种包括矮人，或和矮人有血缘关系的生物。\n\n矮人亚种生物有60尺黑暗视觉。"},
[ust_gnm]={n="侏儒"			,d="此亚种包括侏儒，或和侏儒有血缘关系的生物。\n\n侏儒亚种生物有昏暗视觉。"},
[ust_hfl]={n="半身人"		,d="此亚种包括半身人，或和半身人有血缘关系的生物。"},
[ust_orc]={n="兽人"			,d="此亚种包括兽人，或和兽人有血缘关系的生物，如半兽人。\n\n兽人亚种生物有60尺黑暗视觉和强光敏感（半兽人无强光敏感）。"},
[ust_gob]={n=s_goblinoid	,d=s_goblinoid_d},
[ust_gnl]={n=s_gnoll		,d=s_gnoll_d	},
[ust_cat]={n=s_catfolk		,d=s_catfolk_d	},
[ust_rep]={n="爬虫"			,d="这类生物具有鳞壳并通常是冷血动物。\n\n爬虫亚种仅用来描述一些类人生物种族，而不是那些真正的爬行动物或怪物。"},
[ust_aqu]={n="水栖"			,d="这类生物总是有游泳速度，因此它们可以在水中移动而不需要作游泳检定。\n\n水栖生物可以在水下呼吸。除非它具有两栖特性，否则它不能在水面以上呼吸。"},
[ust_aug]={n="增强"			,d="生物的原始种类发生某种变化时它将获得此亚种。\n\n一些生物（那些具有继承模板的生物）天生属于此亚种；而其它则是在它们获得某一模板的时候成为此亚种。\n\n增强亚种总是和生物的原始种类成对出现。具有增强亚种的生物往往拥有当前种类的特性，却保留原始种类的特征。"},
[ust_fir]={n="火系"			,d="火系亚种的生物免疫火焰，但惧怕寒冷。\n\n寒冷会对它们造成比正常多一半的伤害，无论是否有豁免和是否通过了豁免。"},
[ust_col]={n="寒系"			,d="寒系亚种的生物免疫寒冷，但惧怕火焰。\n\n火焰会对它们造成比正常多一半的伤害，无论是否有豁免和是否通过了豁免。"},
[ust_air]={n="风系"			,d="此亚种包括和风元素位面相关的元素和异界生物。\n\n风系生物总是具有飞行速度且常常有完美的飞行机动性。"},
[ust_wtr]={n="水系"			,d="此亚种包括和水元素位面相关的元素和异界生物。\n\n水系生物总是具有游泳速度，在水中移动时不需要进行游泳检定。\n\n水系生物可以在水下呼吸，通常也可以呼吸空气。"},
[ust_eth]={n="土系"			,d="此亚种包括和土元素位面相关的元素和异界生物。\n\n土系生物通常具有掘穴速度，且大多数都可以挖掘开坚硬的石头。"},
[ust_goo]={n="善良"			,d="此亚种通常只适用于居住在善良阵营外位面上的异界生物。\n\n绝大多数此亚种生物也具有善良阵营；但如果他们的阵营发生变化，他们仍然维持此亚种不变。\n\n在计算依赖于阵营的效果影响时，无论本身阵营如何善良亚种的生物都被视为善良阵营。它也会同样因为它的自身实际阵营而受到影响。\n\n善良亚种的生物在对抗伤害减免时，它的天生武器和任何持有的武器都视作具有善良阵营。"},
[ust_evl]={n="邪恶"			,d="此亚种通常只适用于居住在邪恶阵营外位面上的异界生物。\n\n绝大多数此亚种生物也具有邪恶阵营；但如果他们的阵营发生变化，他们仍然维持此亚种不变。\n\n在计算依赖于阵营的效果影响时，无论本身阵营如何邪恶亚种的生物都被视为邪恶阵营。它也会同样因为它的自身实际阵营而受到影响。\n\n邪恶亚种的生物在对抗伤害减免时，它的天生武器和任何持有的武器都视作具有邪恶阵营。\n\n邪恶的异界生物也常被称作妖魔。"},
[ust_law]={n="守序"			,d="此亚种通常只适用于居住在守序阵营外位面上的异界生物。\n\n绝大多数此亚种生物也具有守序阵营；但如果他们的阵营发生变化，他们仍然维持此亚种不变。\n\n在计算依赖于阵营的效果影响时，无论本身阵营如何守序亚种的生物都被视为守序阵营。它也会同样因为它的自身实际阵营而受到影响。\n\n守序亚种的生物在对抗伤害减免时，它的天生武器和任何持有的武器都视作具有守序阵营。"},
[ust_cho]={n="混乱"			,d="此亚种通常只适用于居住在混乱阵营外位面上的异界生物。\n\n绝大多数此亚种生物也具有混乱阵营；但如果他们的阵营发生变化，他们仍然维持此亚种不变。\n\n在计算依赖于阵营的效果影响时，无论本身阵营如何混乱亚种的生物都被视为混乱阵营。它也会同样因为它的自身实际阵营而受到影响。\n\n混乱亚种的生物在对抗伤害减免时，它的天生武器和任何持有的武器都视作具有混乱阵营。"},
[ust_nat]={n="本地"			,d="此亚种只针对异界生物。这些生物存在凡人祖先，或与主物质位面有牢固的联系，并且可以象其他生物一样被复生、转生或复活。\n\n属于此亚种的生物是主物质位面的本地居民（即这个亚种名称的来由）。\n\n不象真正的异界生物，本地异界生物需要进食和睡眠。"},
[ust_ext]={n="跨位面"		,d="此亚种指那些不在它原本所属位面的生物。一个在位面间旅行的生物在转移位面时可能获得或失去此亚种。\n\n相关描述中假定生物之间的遭遇发生在主物质位面，于是那些原本不属于主位面的生物都是跨位面亚种（但当它在其原始位面的时候便不是了）。\n\n跨位面生物描述中都注明了原本所属的位面。未标明跨位面的生物都属于主物质位面，当他们离开主物质位面的时候将获得此亚种。\n\n正处于过渡位面，如星界、灵界位面和阴影位面的生物不会获得跨位面亚种。"},


[ust_ang]={n=s_angel		,d=s_angel_d.."\n\n"..[[
<b>特性：</b>
- 黑暗视觉60尺和昏暗视觉。
- 免疫强酸、寒冷和石化。
- 电击抗力10，火焰抗力10。
- 毒素豁免+4种族加值。
- 防护灵气（超自然能力）：天使周围20尺以内的任何人对抗邪恶生物作出的攻击或产生的效果时，防御等级+4偏斜加值，豁免+4抗力加值。此外，它的作用还相当于反邪恶法阵和次级防护法球的效果，半径均为20尺（施法者等级等同于天使的HD）。此灵气可被驱散，但天使可以在下一回合以一个自由动作再次创造它。（法阵的防御优势未计入天使的数据。）
- 巧言（超自然能力）：所有天使都能够和任何有语言的生物交谈，如同巧言术（施法者等级等同于天使的HD）。此能力始终处于启动状态。]]},


[ust_arc]={n=s_archon		,d=s_archon_d.."\n\n"..[[
<b>特性：</b>
- 黑暗视觉60尺和昏暗视觉。
- 免疫电击和石化。
- 毒素豁免+4种族加值。
- 威吓灵气（超自然能力）：一股正义的灵气环绕着战斗中或愤怒的神使。神使身旁20尺半径内的任何敌对生物必须成功地通过一次意志豁免来抵抗它的效果。豁免DC基于魅力，并包含+2种族加值，具体数值因神使类型的不同而变化。豁免失败者在攻击、防御等级和豁免上受到-2减值，持续24小时或直到他们成功击中了产生此灵气的神使为止。已成功抵抗或破除此效果的生物在24小时内不会再被同一神使的灵气影响。
- 反邪恶法阵（超自然能力）：反邪恶法阵效果始终环绕着神使（施法者等级等同于神使的HD）。（法阵的防御优势未计入神使的数据。）
- 传送（超自然能力）：神使可以任意使用高等传送术，相当于同名法术（施法者等级14），但她只能传送自己，外加不超过50磅的物体。
- 巧言（超自然能力）：所有神使都能够和任何有语言的生物交谈，如同巧言术（施法者等级14）。此能力始终处于启动状态。]]},


[ust_shp]={n="变形生物"	,d=[[变形生物具有某种超自然能力可以呈现出一种或多种变化形态。许多魔法效果都可以做到某种外形上的改变，并非所有能改变外形的生物都具有变形生物亚种。

<b>特性：</b>
- 擅长它的天生武器、简易武器和所使用武器。
- 如有穿戴盔甲，则擅长此盔甲同类或更轻的盔甲，以及盾牌。]]},


[ust_inc]={n="虚体"	,d=[[虚体生物不具备肉体。只有其他虚体生物、魔法武器或使用魔法武器攻击的生物、法术、类法术能力或超自然能力能对它造成伤害。它免疫所有非魔法攻击。即便被法术或魔法武器击中，它仍有50%机会忽略来自于实体的伤害（除了正能量、负能量、力场作用例如魔法飞弹、或由幽冥武器发起的攻击）。虽然不属于魔法攻击，但圣水可以影响虚体不死生物，尽管圣水的作用仍有50%的机会无法影响到虚体。

虚体生物没有天生防御加值，但具有等同于它魅力加值的偏斜加值（至少为+1，即使生物的魅力值没有提供加值）。

虚体生物可以随意进入或者穿过固体物质，但必须要和物体的外表面相接，因此无法完全穿过一个比它自身空间更大的物体。这时它可以感知它所在位置相邻方格中生物或物体的存在，但敌人对于在物体中的虚体仍然存在完全隐蔽（50%失手几率）。为了从物体中看得更远并进行正常攻击，虚体必须从物体中浮现出来。在物体中的虚体具有全掩蔽，但当它攻击物体外的生物时它仅存在掩蔽，因此外面的生物可以用准备动作在它展开攻击时进行攻击。虚体生物无法穿过力场效果。

虚体生物的攻击可以穿透（忽略）天生防御、盔甲和盾牌，但偏斜加值和力场效果（比如法师护甲）对它有效。虚体生物可以象在空气中那样在水中穿过或进行动作。虚体生物不会坠落或受到坠落伤害。虚体不可以展开绊摔或擒抱攻击，也无法被绊摔或被擒抱。实际上，它们无法作出任何有关实质形体的动作，来针对一个对手或其装备进行挪动或操作，反之这类动作也对它们无效。虚体生物没有体重，也不会触发那些由重量触发的陷阱。

虚体生物移动时很安静，只要它不想被听到，通过聆听检定是无法觉察的。它没有力量属性，因此它的近战和远程攻击都使用它的敏捷调整值。视力以外的手段，比如灵敏嗅觉或盲视，在针对虚体时或者无效，或者仅部分有效。虚体生物对方向有着天生的感知，即使它们看不见也可以全速移动。]]},


[ust_swm]={n="集群"	,d=[[集群由一大群密集的超微型、微型或超小型生物组成，它们在行动方式上看作是一个生物。这些生物在分成小群时没有什么威胁，但聚到足够的数量之后会变得相当危险。

许多不同的生物都可以组成集群：蝙蝠集群、蜈蚣集群、黄蜂集群、蝗虫集群、老鼠集群和蜘蛛集群。集群的生物类别和组成生物的天然类别一样（大多数是动物或虫类），但所有集群都有集群亚种。

除了如下的说明之外，一个集群具有组成它的个体种类的性质。集群有单一的生命骰和生命值，单一的先攻调整值，单一的移动速度，以及单一的防御等级。集群在进行豁免检定时亦和单个生物一样。

一个集群占据边长10尺的正方形（如果由不会飞的生物组成）或立方体（由飞行生物组成），但和组成它的生物一样触及为0尺。

在攻击时，它会移进对手所占据的空间，这可能引发借机攻击。

由于它会附着在猎物身上，因此可以和任意大小的生物一起占据共同的空间，但在10英尺空间内依然是单一的生物。

集群无法进行借机攻击，但能引发借机攻击。

集群可以不受阻碍的穿越敌人占据的方格，反之也如此，但集群这么做会引发借机攻击。

和其他占据10英尺空间的生物不同，集群的形状可以改变。它可以占据任意四个邻接的方格，并且任何空间只要能容纳一只组成集群的生物，这个集群就能够穿越它。如果一个裂缝或者洞口足够组成集群的生物通过，那么集群也可以通过。

一群超小型生物包含300只不会飞的生物或1,000只飞行生物。
一群微型生物包含1,500只不会飞的生物或5,000只飞行生物。
而一群超微型生物包含10,000只生物，无论会飞与否。

在不会飞的集群中，生物通常是紧紧地堆叠在一起，在移动和进攻时翻越其它的个体一起向猎物涌去，所以它们具有比10尺见方通常能容纳的多得多的数量。更大的集群可由多个单个集群的总和来体现。大型集群所占据的区域形状可以随意改变，但是集群通常会保持所占据方格都是相邻的，即巨型的聚落可被分为互相贴近的几个集群。

<b>特性：</b>
由微型和超微型生物组成的集群免疫所有武器伤害。
由超小型生物组成的集群对于挥砍或穿刺武器只受一半伤害。
集群没有明显的前胸后背也不存在明确的生理结构，因此它不受重击和夹击。
集群不会被绊摔、擒抱或冲撞，也无法擒抱对手。
免疫针对具体数目生物的法术或效果（包括单目标法术比如解离术），但如果集群有智力值和群体意识，则影响心灵的效果例外。
将一个集群的生命值减到0或更低可以将它打散，但直到该数目以前的伤害都无法降低它攻击和抵御攻击的能力。集群从不会因受伤而失去战斗力或者处于濒死状态。
影响区域的法术或效果可对集群额外造成一半的伤害，比如泼溅武器和许多塑能系法术。
由微型或超微型生物组成的集群易受强风的影响。在决定风对于集群的影响时，集群看作具有和组成它的生物相同的体型。因为受到非致命伤害而昏迷的集群会乱作一团并分散开，只有在它的生命值超过它所受非致命伤害时才会重新组织起来。

<b>集群的弱点：</b>用物理攻击对战集群极其困难。但集群有一些特殊的弱点。
挥舞点燃的火把作为临时武器每击会造成1d3的火焰伤害。
拥有炽焰或冻寒等特性的武器每击会对其造成完整的能量伤害，尽管武器的正常伤害无法影响集群。
点燃的提灯可作为投掷武器，对其炸开的邻接方格中所有生物造成1d4火焰伤害。


<b>集群攻击：</b>具有集群的生物不会展开通常的近身攻击。取而代之，它们不需要进行攻击检定即可对它们移动结束时所占据格子中的任何生物自动造成伤害。集群攻击没有攻击加值，也不受隐蔽或掩蔽所带来的失手几率的影响。

一个集群造成的伤害基于它的HD，如下：
集群HD		集群基本伤害
1-5		1d6
6-10		2d6
11-15		3d6
16-20		4d6
21+		5d6

除非特别说明，集群攻击是没有魔法性质的。假如一个生物具有足够将集群攻击伤害抵消到0的伤害减免、是虚体或是具有一些其他特性，则通常可免疫（或至少可抵消一些）来自一个集群的攻击伤害。一些集群在造成正常伤害的同时还会造成附加的酸、毒、吸血或者其他特殊攻击。


集群并不威胁同一方格中的生物，也无法用它的集群攻击作出借机攻击。但是，它们能扰乱他们所占据方格内的对手的心神，见下面描述。

<b>扰乱心神（特异能力）：</b>任何易受集群伤害的活物，在它回合开始时若和一个集群在同一个方格内，会反胃一回合；通过强韧豁免（DC = 10 + 1/2集群HD + 它的体质调整值）则不受影响。在集群占据范围中施法或维持专注需要进行专注检定（DC = 20 + 法术等级）。这种情况下，使用需要耐心和集中精神的技能也需要进行DC20的专注检定。]]},
}